package io.github.jonnyfrick.musicbootcamp.core.audio

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * What the player really played in a recorded run, where it was not the given notes: the truth
 * the recognition is measured against. Stored next to the recording (`<name>.played.json`).
 */
@Serializable
data class PlayedLabels(
    val version: Int = 1,
    /** When saved (milliseconds since 1970), to take the latest where a browser kept several copies. */
    val savedAt: Long = 0,
    /**
     * Per step (1-based): the notes played; empty: nothing; null: something else, not known what
     * (the step is left out of the measurement). Steps not listed were played as given.
     */
    val played: Map<Int, List<Int>?> = emptyMap(),
) {
    fun toJson(): String = json.encodeToString(serializer(), this)

    companion object {
        private val json = Json { prettyPrint = true; ignoreUnknownKeys = true }

        fun fromJson(text: String): PlayedLabels = json.decodeFromString(serializer(), text)

        /** The file name next to recording [wavName] (`session-….wav`). */
        fun fileNameFor(wavName: String) = wavName.removeSuffix(".wav") + ".played.json"
    }
}
