package io.github.jonnyfrick.musicbootcamp.core.pitch

import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.sin

/** In-place iterative radix-2 FFT; [re] and [im] must have the same power-of-two size. */
internal fun fft(re: DoubleArray, im: DoubleArray, inverse: Boolean = false) {
    require(re.size == im.size) { "FFT arrays must have the same size" }
    fft(re, im, re.size, inverse)
}

/**
 * The forward FFT of the real signal in [re] (whatever [im] holds is ignored), the same as [fft]
 * with zeros in [im], in about half the time: the signal's even and odd samples are transformed as
 * one complex signal of half the size, and the two spectra separated from it.
 */
internal fun fftReal(re: DoubleArray, im: DoubleArray) {
    val n = re.size
    require(n == im.size && n >= 4 && n and (n - 1) == 0) { "FFT size must be a power of two" }
    val m = n / 2
    // z[k] = x[2k] + i·x[2k+1]; reading index 2k and 2k+1 never meets what is already written.
    for (k in 0 until m) {
        im[k] = re[2 * k + 1]
        re[k] = re[2 * k]
    }
    fft(re, im, m, inverse = false)
    // X[k] = E[k] + w^k·O[k], with E[k] = (Z[k] + conj Z[m-k]) / 2, O[k] = (Z[k] - conj Z[m-k]) / 2i
    // and w = e^(-2πi/n); X[k] and X[m-k] need the same two values, so they are done in pairs.
    val z0Re = re[0]
    val z0Im = im[0]
    re[0] = z0Re + z0Im
    im[0] = 0.0
    re[m] = z0Re - z0Im
    im[m] = 0.0
    val angle = -2 * PI / n
    val stepRe = cos(angle)
    val stepIm = sin(angle)
    var wRe = stepRe
    var wIm = stepIm
    for (k in 1..m / 2) {
        val j = m - k
        val aRe = re[k]
        val aIm = im[k]
        val bRe = re[j]
        val bIm = im[j]
        // X[k] = E + w^k O, from Z[k] = a and Z[m-k] = b.
        val eRe = (aRe + bRe) / 2
        val eIm = (aIm - bIm) / 2
        val oRe = (aIm + bIm) / 2
        val oIm = -(aRe - bRe) / 2
        re[k] = eRe + wRe * oRe - wIm * oIm
        im[k] = eIm + wRe * oIm + wIm * oRe
        // X[m-k] = conj(E) + w^(m-k) conj(O), and w^(m-k) = -conj(w^k).
        re[j] = eRe - (wRe * oRe - wIm * oIm)
        im[j] = -eIm + (wRe * oIm + wIm * oRe)
        val nextRe = wRe * stepRe - wIm * stepIm
        wIm = wRe * stepIm + wIm * stepRe
        wRe = nextRe
    }
    // The upper half mirrors the lower one.
    for (k in 1 until m) {
        re[n - k] = re[k]
        im[n - k] = -im[k]
    }
}

/** The FFT of the first [n] values of [re] and [im]. */
private fun fft(re: DoubleArray, im: DoubleArray, n: Int, inverse: Boolean) {
    require(n > 0 && n and (n - 1) == 0) { "FFT size must be a power of two" }

    // Bit-reversal permutation.
    var j = 0
    for (i in 1 until n) {
        var bit = n shr 1
        while (j and bit != 0) {
            j = j xor bit
            bit = bit shr 1
        }
        j = j xor bit
        if (i < j) {
            re[i] = re[j].also { re[j] = re[i] }
            im[i] = im[j].also { im[j] = im[i] }
        }
    }

    var length = 2
    val sign = if (inverse) 1.0 else -1.0
    while (length <= n) {
        val angle = sign * 2 * PI / length
        val stepRe = cos(angle)
        val stepIm = sin(angle)
        for (start in 0 until n step length) {
            var wRe = 1.0
            var wIm = 0.0
            for (k in 0 until length / 2) {
                val a = start + k
                val b = a + length / 2
                val tRe = re[b] * wRe - im[b] * wIm
                val tIm = re[b] * wIm + im[b] * wRe
                re[b] = re[a] - tRe
                im[b] = im[a] - tIm
                re[a] += tRe
                im[a] += tIm
                val nextRe = wRe * stepRe - wIm * stepIm
                wIm = wRe * stepIm + wIm * stepRe
                wRe = nextRe
            }
        }
        length = length shl 1
    }

    if (inverse) {
        for (i in 0 until n) {
            re[i] /= n
            im[i] /= n
        }
    }
}

internal fun nextPowerOfTwo(value: Int): Int {
    var size = 1
    while (size < value) size = size shl 1
    return size
}
