package io.github.jonnyfrick.musicbootcamp.web

import io.github.jonnyfrick.musicbootcamp.core.pitch.NoteModel
import io.github.jonnyfrick.musicbootcamp.platform.PackedAudio
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlin.coroutines.resume
import kotlin.coroutines.resumeWithException

/**
 * Spotify's Basic Pitch in the browser: onnxruntime-web (WebAssembly, loaded from a CDN only when
 * the model is first used) runs it in a web worker, so it never holds up the page or the sound;
 * the model file comes with the web app (`basic-pitch/nmp.onnx`). Windows and results cross as
 * strings ([PackedAudio]). Once loaded, the worker times a few runs, and the model runs as often
 * as that device affords ([hopFrames]): every quarter of a second on a phone that manages it.
 */
internal class WebNoteModel : NoteModel {
    private val id = modelStart(MODEL_PATH, NoteModel.WINDOW_SAMPLES)
    private var chosenHop: Int? = null

    /**
     * The shortest of [HOPS] in which a run takes at most [BUDGET] of the time; [SLOW_HOP] until the
     * worker has timed its runs. Fixed once chosen, so an exercise's tolerance and its recognizer agree.
     */
    override val hopFrames: Int
        get() {
            chosenHop?.let { return it }
            val millis = modelRunMillis(id)
            if (millis < 0) return SLOW_HOP
            return (HOPS.firstOrNull { millis <= BUDGET * it * FRAME_MILLIS } ?: SLOW_HOP).also {
                chosenHop = it
                modelLog(id, "a run takes ${millis.toInt()} ms: every $it frames")
            }
        }

    override suspend fun analyse(window: FloatArray): Pair<Array<FloatArray>, Array<FloatArray>> {
        val packed = suspendCancellableCoroutine { continuation ->
            modelRun(id, PackedAudio.pack(window)) { error, result ->
                if (error.isEmpty()) continuation.resume(result) else continuation.resumeWithException(IllegalStateException(error))
            }
        }
        // Notes, then onsets, frame by frame.
        fun output(which: Int) = Array(NoteModel.FRAMES) { frame ->
            PackedAudio.unpack(packed, (which * NoteModel.FRAMES + frame) * NoteModel.NOTES, NoteModel.NOTES)
        }
        return output(0) to output(1)
    }

    override fun close() = modelStop(id)

    private companion object {
        const val MODEL_PATH = "basic-pitch/nmp.onnx"
        val HOPS = listOf(21, 28, 35, 42)
        const val SLOW_HOP = 42
        const val BUDGET = 0.75
        const val FRAME_MILLIS = NoteModel.FRAME_SAMPLES * 1000.0 / NoteModel.SAMPLE_RATE
    }
}

/**
 * Starts a worker that loads onnxruntime-web and the model at [path] (relative to the page), then
 * times three runs on [size] samples of silence (the first is slow, the others tell the device's pace); returns its id.
 */
private fun modelStart(path: String, size: Int): Int = js(
    """(function () {
        var s = globalThis.__mbc;
        var id = ++s.nextId;
        // 1.18.0: later versions ask for more memory than iOS grants (see MIGRATION.md). The bundle
        // with only the WebAssembly backend: a quarter of the size, loaded in a ninth of the time,
        // with the same WebAssembly and results as the full one.
        var ort = 'https://cdn.jsdelivr.net/npm/onnxruntime-web@1.18.0/dist/';
        var code =
            "importScripts('" + ort + "ort.wasm.min.js');" +
            "ort.env.wasm.numThreads = 1; ort.env.wasm.wasmPaths = '" + ort + "';" +
            "var session = null; var ready = null;" +
            "function run(window) {" +
            "  var input = new ort.Tensor('float32', window, [1, window.length, 1]);" +
            "  return session.run({ 'serving_default_input_2:0': input }, ['StatefulPartitionedCall:1', 'StatefulPartitionedCall:2']);" +
            "}" +
            "onmessage = async function (e) {" +
            "  var m = e.data;" +
            "  try {" +
            "    if (m.type === 'load') {" +
            "      ready = (async function () {" +
            "        session = await ort.InferenceSession.create(m.url, { executionProviders: ['wasm'] });" +
            "        var times = [];" +
            "        for (var i = 0; i < 3; i++) { var t = performance.now(); await run(new Float32Array(m.size)); times.push(performance.now() - t); }" +
            "        postMessage({ type: 'timed', millis: Math.max(times[1], times[2]) });" +
            "      })();" +
            "      await ready; return;" +
            "    }" +
            "    await ready;" +
            "    var started = performance.now();" +
            "    var r = await run(m.window);" +
            "    var note = r['StatefulPartitionedCall:1'].data, onset = r['StatefulPartitionedCall:2'].data;" +
            "    postMessage({ note: note, onset: onset, millis: performance.now() - started }, [note.buffer, onset.buffer]);" +
            "  } catch (error) { postMessage({ error: String(error) }); }" +
            "};";
        var worker = new Worker(URL.createObjectURL(new Blob([code], { type: 'application/javascript' })));
        // What the runs cost, for the page's start log: in the worker, and from sending a window to
        // its answer being taken (longer when the page's main thread is busy).
        var model = { worker: worker, done: null, millis: -1, runs: 0, runMillis: 0, longestRun: 0, roundMillis: 0, longestRound: 0, sent: 0 };
        worker.onmessage = function (e) {
            if (e.data.type === 'timed') { model.millis = e.data.millis; return; }
            if (e.data.millis !== undefined) {
                var round = performance.now() - model.sent;
                model.runs++;
                model.runMillis += e.data.millis; model.longestRun = Math.max(model.longestRun, e.data.millis);
                model.roundMillis += round; model.longestRound = Math.max(model.longestRound, round);
            }
            var done = model.done; model.done = null;
            if (!done) return;
            if (e.data.error) done(e.data.error, ''); else done('', s.pack([e.data.note, e.data.onset]));
        };
        worker.onerror = function (e) { var done = model.done; model.done = null; if (done) done(String(e.message || 'worker failed'), ''); };
        worker.postMessage({ type: 'load', url: new URL(path, location.href).href, size: size });
        s.models = s.models || {};
        s.models[id] = model;
        return id;
    })()""",
)

/** How long a run of model [id] takes on this device in milliseconds, or -1 while not timed yet. */
private fun modelRunMillis(id: Int): Double = js("(function () { var m = globalThis.__mbc.models[id]; return m ? m.millis : -1; })()")

/** Sends a window ([PackedAudio]) to model [id]; [done] gets "" and the notes and onsets packed, or an error. */
private fun modelRun(id: Int, packed: String, done: (String, String) -> Unit): Unit = js(
    """{
        var s = globalThis.__mbc;
        var model = s.models[id];
        var window = s.unpack(packed, 0, packed.length);
        model.done = done;
        model.sent = performance.now();
        model.worker.postMessage({ type: 'run', window: window }, [window.buffer]);
    }""",
)

private fun modelStop(id: Int): Unit = js(
    """{
        var s = globalThis.__mbc;
        var model = s.models && s.models[id];
        if (model) {
            if (window.mbcLog && model.runs) window.mbcLog('model ' + id + ': ' + model.runs + ' runs, in the worker ' +
                Math.round(model.runMillis / model.runs) + ' ms (longest ' + Math.round(model.longestRun) + '), sent to answered ' +
                Math.round(model.roundMillis / model.runs) + ' ms (longest ' + Math.round(model.longestRound) + ')');
            model.worker.terminate();
            delete s.models[id];
        }
    }""",
)

/** A line for the page's start log (index.html) about model [id]. */
private fun modelLog(id: Int, text: String): Unit = js("{ if (window.mbcLog) window.mbcLog('model ' + id + ': ' + text); }")
