package io.github.jonnyfrick.musicbootcamp.platform

/**
 * Samples and bytes packed into a string, one code unit each, to cross between Kotlin and the
 * browser's JavaScript in one call instead of one per value (WebAssembly pays for every call
 * across). Samples (-1..1) keep 15 bits, codes below the surrogate range so every string is
 * valid; the JavaScript side (WebServices.kt) packs and unpacks the same way.
 */
object PackedAudio {
    const val ZERO = 16384
    const val SCALE = 16383f

    fun code(sample: Float): Int = (sample.coerceIn(-1f, 1f) * SCALE).let { if (it >= 0) it + 0.5f else it - 0.5f }.toInt() + ZERO

    fun pack(samples: FloatArray, offset: Int = 0, length: Int = samples.size - offset): String =
        CharArray(length) { code(samples[offset + it]).toChar() }.concatToString()

    /** [length] samples of [packed] from [start] on. */
    fun unpack(packed: String, start: Int = 0, length: Int = packed.length - start): FloatArray =
        FloatArray(length) { (packed[start + it].code - ZERO) / SCALE }

    fun packBytes(bytes: ByteArray): String = CharArray(bytes.size) { (bytes[it].toInt() and 0xFF).toChar() }.concatToString()
}
