package io.github.jonnyfrick.musicbootcamp.core.practice

import io.github.jonnyfrick.musicbootcamp.core.learning.LearnedSequences
import io.github.jonnyfrick.musicbootcamp.core.midi.MidiMessage
import io.github.jonnyfrick.musicbootcamp.core.midi.MidiOutput
import io.github.jonnyfrick.musicbootcamp.core.model.KotlinRandomSource
import io.github.jonnyfrick.musicbootcamp.core.model.PracticeSettings
import io.github.jonnyfrick.musicbootcamp.core.model.RandomSource
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.Job
import kotlinx.coroutines.cancelAndJoin
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import kotlin.time.Duration
import kotlin.time.Duration.Companion.milliseconds
import kotlin.time.TimeMark
import kotlin.time.TimeSource

/** Live figures of a running exercise, for the UI. */
data class PracticeStatus(
    val running: Boolean = false,
    val steps: Int = 0,
    val correct: Int = 0,
    val wrong: Int = 0,
    val storedMistakes: Int = 0,
    val given: List<Int> = emptyList(),
    val lastCorrect: Boolean? = null,
    /** The newest step whose answer is judged, right away and not only when it is evaluated. */
    val lastResult: StepVerdict? = null,
    /** A run with a fixed number of notes has given and evaluated all of them. */
    val finished: Boolean = false,
)

/**
 * Runs a [PracticeSession] on a clock (Java: `java.util.Timer` with the practice
 * `TimerTask`s and `TurnNoteOffTimerTask`).
 *
 * All session access — steps and incoming MIDI — happens on one confined
 * dispatcher, so the session needs no locking.
 *
 * With a [lateAnswerTolerance], a step still without an answer when the next note starts stays
 * open for that much longer, so a key press arriving after the change can still answer it —
 * at a fast tempo also after several later notes have started (see [PracticeSession.onMidiInput]).
 */
@OptIn(ExperimentalCoroutinesApi::class)
class PracticeRunner(
    private val scope: CoroutineScope,
    private val settings: PracticeSettings,
    memory: LearnedSequences,
    private val output: MidiOutput,
    private val input: Flow<MidiMessage>,
    random: RandomSource = KotlinRandomSource(),
    lateAnswerTolerance: Duration = Duration.ZERO,
    /** An answer with the right pitch classes counts as the given one, in whatever octave (see [PracticeSession]). */
    octavesCountAsCorrect: Boolean = false,
    /** Ends the run after this many notes (the last one is still evaluated); null = until stopped. */
    private val maxSteps: Int? = null,
    /** Called on the session dispatcher after every step, e.g. to log it. */
    private val onStep: (StepResult) -> Unit = {},
    /** Called on the session dispatcher for every late [Evaluation]. */
    private val onEvaluation: (Evaluation) -> Unit = {},
    /** Called on the session dispatcher with what became of every answer. */
    private val onAssignment: (Assignment) -> Unit = {},
    /**
     * Awaited before the first note, while the input is already listened to: e.g. until the
     * microphone really delivers sound, so the first note (the one the player cannot be playing
     * along with yet) is heard in full.
     */
    private val beforeFirstStep: suspend () -> Unit = {},
    private val sessionDispatcher: CoroutineDispatcher = Dispatchers.Default.limitedParallelism(1),
    /**
     * With late answers: what is recognised sooner after a step began answers only older steps,
     * as the player cannot have heard its note yet; add the output's buffer (see [REACTION_TIME]).
     */
    private val reactionTime: Duration = REACTION_TIME,
    /**
     * Latency beyond what the tolerance and the reaction time allow for, as it becomes known (a
     * Bluetooth loudspeaker's, say): the player hears each note that much later, so both grow by it.
     */
    private val extraLatency: () -> Duration = { Duration.ZERO },
    /**
     * How long ago the note of an input message was struck (a recognition that decides after an
     * analysis window reports it later); the reaction time is judged from the stroke.
     */
    private val strokeAge: (MidiMessage) -> Duration = { Duration.ZERO },
    /**
     * How long after a step begins the player hears its note, on the clock of the input (with the
     * microphone: when the note reaches it). An answer struck after the next note was heard is late.
     */
    private val audibleDelay: () -> Duration = { Duration.ZERO },
    /** For when a step began. */
    private val timeSource: TimeSource = TimeSource.Monotonic,
) {
    private val session = PracticeSession(settings, memory, random, octavesCountAsCorrect, output = output)
    private val _status = MutableStateFlow(PracticeStatus())
    val status: StateFlow<PracticeStatus> = _status.asStateFlow()

    private val tolerance = lateAnswerTolerance
    private var stepStarted: TimeMark? = null
    private val stepStarts = mutableListOf<TimeMark>()
    /** When the stroke behind the latest input was struck. */
    private var lastStroke: TimeMark? = null

    private var jobs: List<Job> = emptyList()

    fun start() {
        if (jobs.isNotEmpty()) return
        _status.value = PracticeStatus(running = true)
        val inputJob = scope.launch(sessionDispatcher) {
            input.collect { message ->
                // With late answers: what is heard before the player can have reacted to the
                // current note answers an older one (see PracticeSession.onMidiInput).
                // A stroke from before the step began cannot answer it either.
                receive(message, strokeAge(message))
            }
        }
        val clockJob = scope.launch(sessionDispatcher) {
            beforeFirstStep()
            // Like Timer.schedule(task, 0, period): first step immediately, then fixed delay.
            var given = 0
            while (isActive) {
                if (maxSteps != null && given >= maxSteps) {
                    // No next note follows the last one, so its answer may take up to one more step.
                    delay(tolerance + extraLatency())
                    var waited = 0L
                    while (!session.allAnswered() && waited < settings.stepPeriodMillis) {
                        delay(END_POLL_MILLIS)
                        waited += END_POLL_MILLIS
                    }
                    session.end().forEach(::report)
                    publishVerdicts()
                    _status.update { it.copy(finished = true) }
                    break
                }
                given++
                val result = session.step(deferEvaluation = tolerance > Duration.ZERO)
                stepStarted = timeSource.markNow().also { stepStarts += it }
                result.startedNotes.forEach { note ->
                    launch {
                        delay(settings.noteDurationMillis)
                        output.send(MidiMessage.noteOff(note))
                    }
                }
                _status.update { it.after(result).with(session.takeVerdicts()) }
                onStep(result)
                result.openStep?.let { number ->
                    launch {
                        delay(tolerance + extraLatency())
                        session.expire(number).forEach(::report)
                        publishVerdicts()
                    }
                }
                delay(settings.stepPeriodMillis)
            }
        }
        jobs = listOf(inputJob, clockJob)
    }

    /** An answer from the keyboard on the screen: it sounds like the app's notes and counts like a key on a MIDI keyboard. */
    fun play(note: Int) {
        val listening = jobs.firstOrNull() ?: return
        scope.launch(sessionDispatcher + listening) {
            val message = MidiMessage.noteOn(note, settings.midiOutVelocity)
            output.send(message)
            receive(message, Duration.ZERO)
            delay(settings.noteDurationMillis)
            output.send(MidiMessage.noteOff(note))
        }
    }

    private fun receive(message: MidiMessage, age: Duration) {
        lastStroke = timeSource.markNow() - age
        val early = tolerance > Duration.ZERO && stepStarted?.let { it.elapsedNow() - age < reactionTime + extraLatency() } == true
        session.onMidiInput(message, beforeReaction = early).forEach(::report)
        publishVerdicts()
    }

    /** Stops the clock, cancels pending note-offs and silences the output. */
    suspend fun stop() {
        jobs.forEach { it.cancelAndJoin() }
        jobs = emptyList()
        withContext(sessionDispatcher) { output.send(MidiMessage.allNotesOff()) }
        _status.update { it.copy(running = false) }
    }

    companion object {
        private const val END_POLL_MILLIS = 20L

        /**
         * The shortest time from a note starting to an answer to it being recognised: the player
         * hears it (after the output's buffer), reacts, and the recognition confirms the note.
         */
        val REACTION_TIME = 400.milliseconds
    }

    private fun report(evaluation: Evaluation) {
        onEvaluation(evaluation)
        _status.update {
            it.copy(
                correct = it.correct + if (evaluation.correct) 1 else 0,
                wrong = it.wrong + if (evaluation.correct) 0 else 1,
                storedMistakes = it.storedMistakes + if (evaluation.storedMistake) 1 else 0,
                lastCorrect = evaluation.correct,
            )
        }
    }

    private fun publishVerdicts() {
        session.takeAssignments().forEach { onAssignment(it.timed()) }
        val verdicts = session.takeVerdicts()
        if (verdicts.isNotEmpty()) _status.update { it.with(verdicts) }
    }

    /** Whether a counted answer was struck once the next step's note could be heard. */
    private fun Assignment.timed(): Assignment {
        if (use != AnswerUse.COUNTED || step == null) return this
        val next = stepStarts.getOrNull(step + 1) ?: return copy(late = false)
        val stroke = lastStroke ?: return copy(late = true)
        return copy(late = next.elapsedNow() - stroke.elapsedNow() >= audibleDelay())
    }

    /** A verdict on an older step (e.g. one given up late) does not replace a newer one. */
    private fun PracticeStatus.with(verdicts: List<StepVerdict>) = verdicts.fold(this) { status, verdict ->
        val last = status.lastResult
        if (last == null || verdict.step >= last.step) status.copy(lastResult = verdict) else status
    }

    private fun PracticeStatus.after(result: StepResult) = copy(
        steps = steps + 1,
        correct = correct + if (result.previousCorrect == true) 1 else 0,
        wrong = wrong + if (result.previousCorrect == false) 1 else 0,
        storedMistakes = storedMistakes + if (result.storedMistake) 1 else 0,
        given = result.given,
        lastCorrect = result.previousCorrect ?: lastCorrect,
    )
}
