package io.github.jonnyfrick.musicbootcamp.core.audio

import kotlin.math.sqrt

/**
 * Tells a microphone that delivers no signal from one that does: an audio interface chosen as
 * input with nothing plugged in, a device that went away, a muted input. Such an input delivers
 * exact zeros or only its own faint noise, far below anything played or sung near a microphone.
 *
 * Fed blocks: [Verdict.SOUND] as soon as a stretch of [STRETCH_MILLIS] is louder than
 * [threshold] (RMS, full scale 1), [Verdict.SILENT] once [seconds] passed without one,
 * [Verdict.UNDECIDED] before either. It keeps watching, so silence after sound (the microphone
 * unplugged) or sound after silence (plugged in) changes the verdict.
 */
class SilenceWatch(
    sampleRate: Int,
    seconds: Double = DEFAULT_SECONDS,
    private val threshold: Double = DEFAULT_THRESHOLD,
) {
    private val stretch = maxOf(1, sampleRate * STRETCH_MILLIS / 1000)
    private val total = (sampleRate * seconds).toLong()
    private var quiet = 0L
    private var sum = 0.0
    private var count = 0

    var verdict: Verdict = Verdict.UNDECIDED
        private set

    /** Takes the next [samples]; returns the verdict after them. */
    fun process(samples: FloatArray): Verdict {
        for (sample in samples) {
            sum += sample.toDouble() * sample
            if (++count == stretch) {
                if (sqrt(sum / count) > threshold) {
                    verdict = Verdict.SOUND
                    quiet = 0
                } else {
                    quiet += count
                    if (quiet >= total) verdict = Verdict.SILENT
                }
                sum = 0.0
                count = 0
            }
        }
        return verdict
    }

    enum class Verdict { UNDECIDED, SOUND, SILENT }

    companion object {
        /** Long enough for the app's first note, or the player's, to reach the microphone. */
        const val DEFAULT_SECONDS = 6.0

        /**
         * -75 dBFS: an instrument or a voice at the microphone is louder by far; an interface's
         * preamplifier with nothing plugged in is quieter even turned well up.
         */
        const val DEFAULT_THRESHOLD = 1.8e-4

        const val STRETCH_MILLIS = 50
    }
}
