/**
 * UI state and actions of the app (Java: `MusicBootCampMainWindow`, `ParameterManager`
 * and the dialogs' OK handlers). Holds Compose state, so the UI recomposes on changes.
 *
 * Differences to the Java version: settings apply immediately and are saved
 * automatically; learned sequences are saved when an exercise stops and on exit.
 */
class AppController(
    private val services: PlatformServices,
    private val scope: CoroutineScope,
) {
    private val repository = SetupRepository(services.documents)
    private var setup: Setup = Setup(DEFAULT_SETUP_NAME)

    var ready by mutableStateOf(false)
        private set
    var setupNames by mutableStateOf(listOf<String>())
        private set
    var setupName by mutableStateOf(DEFAULT_SETUP_NAME)
        private set
    var settings by mutableStateOf(PracticeSettings())
        private set
    var preferences by mutableStateOf(AppPreferences())
        private set

    /** Sequences per priority level in the memory of the current mode. */
    var memoryCounts by mutableStateOf(List(LearnedSequences.PRIORITY_LEVELS) { 0 })
        private set
    /** Learned sequences of the current mode that reach outside the current range and are skipped. */
    var sequencesOutsideRange by mutableStateOf(0)
        private set
    var status by mutableStateOf(PracticeStatus())
        private set
    /** Streak, recent results and the latest answer as keys, folded from [status]. */
    internal var feedback by mutableStateOf(PracticeFeedback())
        private set
    var inputDevices by mutableStateOf(listOf<String>())
        private set
    var outputDevices by mutableStateOf(listOf<String>())
        private set

    /** A message for the user (snackbar); cleared by [dismissMessage]. */
    var message by mutableStateOf<UiText?>(null)
        private set

    /** True from "Go" until the exercise has stopped and everything is saved. */
    var running by mutableStateOf(false)
        private set

    val midiUnavailableReason: String? get() = services.midi.unavailableReason
    /** Debug builds only: the Java import and the tools for tuning the recognition are available. */
    val debugTools: Boolean get() = services.debugTools
    val canImportLegacyFiles: Boolean get() = debugTools && services.legacyFiles != null

    /**
     * The preferences as far as they tune the recognition: in a release build always the
     * defaults, never recording, whatever a debug build may have stored on this device.
     */
    private val tuning: AppPreferences
        get() = if (debugTools) preferences else preferences.copy(
            recordMicrophone = false,
            optimizationMode = false,
            strokeRecognition = true,
            modelRecognition = false,
            detectionParameters = DetectionParameters(),
            chordDetectionParameters = emptyMap(),
        )

    var audioInputDevices by mutableStateOf(listOf<String>())
        private set

    /** Microphone level (RMS, 0..1) while the microphone is open. */
    var microphoneLevel by mutableStateOf(0.0)
        private set
    var micTesting by mutableStateOf(false)
        private set
    var micTestNote by mutableStateOf<DetectedNote?>(null)
        private set

    /** The microphone test heard no signal at all: probably the wrong input. */
    var micTestSilent by mutableStateOf(false)
        private set

    val audioUnavailableReason: String? get() = services.audio.unavailableReason

    private var runner: PracticeRunner? = null
    private var output: MidiOutputPort? = null
    private var gate: OwnSoundGate? = null
    private var lateAnswerTolerance = Duration.ZERO
    private var recorder: SessionRecorder? = null

    /** The chords given lately, for the chord recognition (read from the audio thread). */
    private val expectedChords = MutableStateFlow<List<List<Int>>>(emptyList())

    /** How long the app's own sound output plays behind (with the microphone, set when it opens). */
    private var outputDelay = Duration.ZERO

    /** How long ago the stroke behind the note-ons being handed to the exercise was struck. */
    private var strokeAge = Duration.ZERO

    /** How long the app's sound takes from the loudspeaker's play head to the microphone, once measured (audio thread). */
    @Volatile private var echoDelay: Duration? = null

    /**
     * Latency beyond what the fixed time windows allow for (the own-sound gate's, the reaction
     * time, the late-answer tolerance): with a loudspeaker the measured delay beyond the 0.3 s a
     * phone's own needs, else what the platform reports beyond 0.1 s (Bluetooth headphones, say).
     */
    private fun extraLatency(): Duration {
        val measured = echoDelay
        if (measured != null) return (measured - USUAL_ECHO_DELAY).coerceAtLeast(Duration.ZERO)
        val reported = (output as? RenderedOutputPort)?.outputLatency ?: return Duration.ZERO
        return (reported - USUAL_OUTPUT_LATENCY).coerceAtLeast(Duration.ZERO)
    }
    /**
     * How long after a step begins its note reaches the microphone, and so (as the player's
     * strokes reach it as late) when the player has heard it: measured, else what the output
     * buffers and the platform reports.
     */
    private fun audibleDelay(): Duration =
        echoDelay ?: (outputDelay + ((output as? RenderedOutputPort)?.outputLatency ?: Duration.ZERO))

    /** The notes the player struck last (MIDI or recognised), written where the exercise runs. */
    private val playedNotes = MutableStateFlow<List<Int>>(emptyList())

    /** The player's piano as measured by calibration; the chord recognition's templates. */
    var learnedTemplates by mutableStateOf(LearnedTemplates())
        private set
    private var recordingInfo: Map<String, String> = emptyMap()

    /** Step by step what the last run in optimization mode recorded; shown on the Practice tab (set by tests too). */
    var runSummary by mutableStateOf<RunSummary?>(null)

    /** The recording [runSummary] shows, for storing what the player says they really played. */
    private var summaryRecording: SessionRecorder? = null

    /**
     * What the player says they really played in the run [runSummary] shows, where it was not the
     * given notes (see [PlayedLabels.played]: empty = nothing, null = something else).
     */
    var playedLabels by mutableStateOf<Map<Int, List<Int>?>>(emptyMap())
        private set

    /** Whether [playedLabels] are stored with the recording. */
    var labelsSaved by mutableStateOf(true)
        private set

    /** Step [step] (1-based) of the last run was played as [played] (see [playedLabels]). */
    fun setPlayed(step: Int, played: List<Int>?) {
        playedLabels = playedLabels + (step to played?.sorted())
        labelsChanged()
    }

    /** Step [step] was played as given after all. */
    fun clearPlayed(step: Int) {
        playedLabels = playedLabels - step
        labelsChanged()
    }

    // Stored at once where that goes unnoticed; else (a browser's downloads) with the button, or
    // at the latest when the next run starts, so a mark is never lost.
    private fun labelsChanged() {
        labelsSaved = false
        if (summaryRecording?.savesLabelsQuietly == true) savePlayedLabels(quiet = true)
    }

    /** Stores [playedLabels] next to the recording, where the analysis of recordings finds them. */
    fun savePlayedLabels(quiet: Boolean = false) {
        val recording = summaryRecording ?: return
        val labels = PlayedLabels(savedAt = Clock.System.now().toEpochMilliseconds(), played = playedLabels)
        launchSafely {
            runCatching { withContext(Dispatchers.Default) { recording.saveLabels(labels) } }
                .onSuccess {
                    if (playedLabels == labels.played) labelsSaved = true
                    if (!quiet) message = text(Res.string.msg_labels_saved)
                }
                .onFailure { message = text(Res.string.msg_recording_failed, it.toUiText()) }
        }
    }

    /** Fixed run length in optimization mode (microphone only); null = until stopped. */
    private val optimizationSteps: Int?
        get() = preferences.optimizationSteps.takeIf {
            tuning.optimizationMode && preferences.inputSource == InputSource.MICROPHONE
        }
    private val closers = mutableListOf<() -> Unit>()
    private var micTestPort: AudioInputPort? = null
    private var micTestJob: Job? = null

    /** The notes just played or heard, whatever the input. */
    var heardKeys by mutableStateOf(setOf<Int>())
        private set
    private val heardJobs = mutableMapOf<Int, Job>()

    var midiTesting by mutableStateOf(false)
        private set

    /** Key presses received during the MIDI test, newest first. */
    var midiTestNotes by mutableStateOf(listOf<MidiMessage>())
        private set
    private var midiTestInput: ReconnectingMidiInput? = null
    private var midiTestOutput: MidiOutputPort? = null

    /** The MIDI keyboard the running exercise listens to, reopened if it drops out for a moment. */
    private var practiceInput: ReconnectingMidiInput? = null
    private var midiTestJob: Job? = null
    private var statusJob: Job? = null
    private var saveJob: Job? = null
    private var preferencesJob: Job? = null

    fun load() {
        launchSafely {
            preferences = repository.loadPreferences().let {
                // Where there is no microphone (or no access to one at all), the keyboard is the input.
                if (it.inputSource == InputSource.MICROPHONE && services.audio.unavailableReason != null) it.copy(inputSource = InputSource.MIDI) else it
            }
            if (debugTools) learnedTemplates = repository.loadTemplates()
            val names = repository.setupNames()
            val initial = preferences.lastSetup?.takeIf { it in names } ?: names.firstOrNull()
            setup = initial?.let { runCatching { repository.load(it) }.getOrNull() } ?: Setup(DEFAULT_SETUP_NAME).also { repository.save(it) }
            refreshSetupState()
            setupNames = repository.setupNames()
            refreshDevices()
            ready = true
            // The learned model, if it will be used: loaded now rather than at the first exercise.
            prepareModel()
            // The piano's samples: decoded in the background, the exercise's range first; until
            // then its notes are synthetic.
            scope.launch {
                val started = TimeSource.Monotonic.markNow()
                runCatching {
                    withContext(Dispatchers.Default) {
                        Instruments.load(settings.lowLimit..settings.highLimit, services.audioDecoder ?: { decodeFlac(it) })
                    }
                }
                pianoSampled = Instruments.isPianoSampled
                samplesLoadedIn = started.elapsedNow()
            }
        }
        launchSafely { services.midi.devicesChanged.collect { onMidiDevicesChanged() } }
    }

    /** Completed when the microphone of the running exercise delivers sound rather than silence. */
    private var microphoneLive = CompletableDeferred<Unit>()

    /** How long decoding all the piano's samples took (logged with recordings). */
    private var samplesLoadedIn: Duration? = null

    /**
     * A MIDI device was plugged in or removed: update the lists and say what changed. A keyboard
     * plugged in is meant to be played on, so it becomes the input at once (the output stays:
     * the app's own synthesizer can remove its sound from the microphone, a keyboard's cannot).
     */
    private fun onMidiDevicesChanged() {
        val inputsBefore = inputDevices.toSet()
        val before = (inputDevices + outputDevices).toSet()
        refreshDevices()
        val after = (inputDevices + outputDevices).toSet()
        val added = after - before
        val removed = before - after
        if (added.isEmpty() && removed.isEmpty()) return
        // A device in use that dropped out for a moment (a loose cable) is opened again as it was.
        val inUse = listOfNotNull(practiceInput, midiTestInput)
        val outputInUse = output as? ReconnectingMidiOutput
        val usedNames = (inUse.map { it.deviceName } + listOfNotNull(outputInUse?.deviceName)).toSet()
        val back = added intersect usedNames
        inUse.filter { it.deviceName in back }.forEach { it.reconnect() }
        outputInUse?.takeIf { it.deviceName in back }?.reconnect()
        val lost = removed intersect usedNames
        if (back.isNotEmpty() || lost.isNotEmpty()) {
            message = UiText.Joined(
                buildList {
                    if (lost.isNotEmpty()) add(text(Res.string.msg_midi_lost, lost.joinToString()))
                    if (back.isNotEmpty()) add(text(Res.string.msg_midi_back, back.joinToString()))
                },
            )
            if (added.all { it in back } && removed.all { it in lost }) return
        }
        val newInput = inputDevices.firstOrNull { it !in inputsBefore && it != JAVA_SEQUENCER && it !in back }
        if (newInput != null && !running) {
            selectInputDevice(newInput)
            setInputSource(InputSource.MIDI) // the default is the microphone
        }
        message = UiText.Joined(
            buildList {
                if (added.isNotEmpty()) add(text(Res.string.msg_midi_connected, added.joinToString()))
                if (newInput != null && !running) add(text(Res.string.msg_midi_chosen, newInput))
                if (removed.isNotEmpty()) add(text(Res.string.msg_midi_disconnected, removed.joinToString()))
                if (running && added.isNotEmpty()) add(text(Res.string.msg_restart_to_use))
            },
        )
    }

    // ------------------------------------------------------------------ setups

    fun updateSettings(transform: (PracticeSettings) -> PracticeSettings) {
        if (running) return
        setup.settings = transform(setup.settings)
        refreshSetupState()
        scheduleSave()
    }

    fun selectSetup(name: String) {
        if (running || name == setupName) return
        launchSafely {
            saveNow()
            val loaded = runCatching { repository.load(name) }.getOrElse {
                message = text(Res.string.msg_open_setup_failed, name, it.toUiText())
                null
            } ?: return@launchSafely
            setup = loaded
            refreshSetupState()
            updatePreferences { it.copy(lastSetup = name) }
        }
    }

    /** Java: "Save Setup As". Copies settings and learned sequences under a new name. */
    fun saveSetupAs(name: String) {
        if (running) return
        val cleanName = uniqueName(SetupRepository.sanitizeName(name))
        launchSafely {
            saveNow()
            setup = setup.copy(cleanName)
            repository.save(setup)
            setupNames = repository.setupNames()
            refreshSetupState()
            updatePreferences { it.copy(lastSetup = cleanName) }
        }
    }

    fun deleteCurrentSetup() {
        if (running) return
        launchSafely {
            saveJob?.cancel()
            repository.delete(setup.name)
            val remaining = repository.setupNames()
            setup = remaining.firstOrNull()?.let { repository.load(it) } ?: Setup(DEFAULT_SETUP_NAME).also { repository.save(it) }
            setupNames = repository.setupNames()
            refreshSetupState()
            updatePreferences { it.copy(lastSetup = setup.name) }
        }
    }

    /** Forgets every learned sequence of the current mode. */
    fun clearMemory() {
        if (running) return
        setup.memory().clear()
        refreshSetupState()
        scheduleSave()
    }

    /** Imports a Java settings file together with its learned sequences as a new setup. */
    fun importLegacySetup() {
        val picker = services.legacyFiles ?: return
        if (running) return
        launchSafely {
            val selection = runCatching { picker.pickSettingsFile() }.getOrElse {
                message = text(Res.string.msg_import_failed, it.toUiText())
                null
            } ?: return@launchSafely
            saveNow()
            val name = uniqueName(SetupRepository.sanitizeName(selection.suggestedName))
            val result = runCatching { LegacyImport.importSetup(name, selection.settingsXml, selection.readSibling) }
                .getOrElse {
                    message = text(Res.string.msg_import_failed, it.toUiText())
                    return@launchSafely
                }
            setup = result.setup
            repository.save(setup)
            setupNames = repository.setupNames()
            refreshSetupState()
            result.legacySettings.referenceAHz?.let { reference -> updatePreferences { it.copy(referenceAHz = reference) } }
            updatePreferences { it.copy(lastSetup = name) }

            message = UiText.Joined(
                buildList {
                    add(text(Res.string.msg_imported, name, setup.memory().size))
                    result.legacySettings.referenceAHz?.let { add(text(Res.string.msg_imported_reference_a, it)) }
                    result.warnings.forEach { add(UiText.Raw(it)) }
                },
            )
        }
    }

    // ---------------------------------------------------------------- practice

    /** Java: "Go!" in the run dialog. */
    fun startPractice() {
        if (running) return
        val microphone = preferences.inputSource == InputSource.MICROPHONE
        if (microphone && !withMicrophoneAccess(::startPractice)) return
        val problem = when {
            services.midi.unavailableReason != null -> services.midi.unavailableReason?.let(UiText::Raw)
            microphone && services.audio.unavailableReason != null -> services.audio.unavailableReason?.let(UiText::Raw)
            !settings.mode.isImplemented -> text(Res.string.msg_mode_not_implemented)
            settings.intervalPriorities.all { it == 0 } -> text(Res.string.intervals_problem)
            else -> null
        }
        if (problem != null) {
            message = problem
            return
        }
        stopMicTest()
        stopMidiTest()

        // Learned sequences are saved when the exercise stops; no background save may touch them meanwhile.
        saveJob?.cancel()
        outputDelay = Duration.ZERO
        strokeAge = Duration.ZERO
        usesModel = false
        val input = runCatching {
            when (preferences.inputSource) {
                InputSource.MICROPHONE -> openMicrophoneInput(settings)
                InputSource.MIDI -> openMidiInput()
                InputSource.SCREEN_KEYS -> openScreenKeys()
            }
        }.getOrElse {
            closePorts()
            message = text(Res.string.msg_open_input_failed, it.toUiText())
            return
        }
        midiTruthDevice = if (microphone) openMidiTruth() else null
        val heard: MidiOutput = (gate ?: output!!).let { if (preferences.playsGivenNotes) it else it.withoutNotes() }
        val practiceOutput = heard.let { port -> recorder?.recording(port) ?: port }.let { port ->
            // For the learned model: which notes the app sent when, on the microphone's clock.
            if (!usesModel) port else MidiOutput { message ->
                if (message.isNoteOn) sentNotes.value = (sentNotes.value + AppNote(microphoneSamples, message.data1)).takeLast(SENT_NOTES)
                port.send(message)
            }
        }
        recordingInfo = mapOf(
            "breathingTime" to settings.breathingTime.toString(),
            "sustain" to settings.sustain.toString(),
            "lateAnswerToleranceMillis" to settings.lateAnswerToleranceMillis.toString(),
            "usesHeadphones" to noOwnSound.toString(),
            "playsGivenNotes" to preferences.playsGivenNotes.toString(),
            "referenceAHz" to preferences.referenceAHz.toString(),
            "midiOutputDevice" to (preferences.midiOutputDevice ?: ""),
            "optimizationSteps" to (optimizationSteps?.toString() ?: ""),
            "stopsAtMistake" to (optimizationSteps != null && preferences.optimizationStopsAtMistake).toString(),
            "midiTruth" to (midiTruthDevice ?: ""),
            "detectionParameters" to tuning.detectionParameters.toJson(),
            "voices" to settings.mode.voices.toString(),
            "instrument" to preferences.instrument.name,
            "pianoSamplesLoadedMillis" to (samplesLoadedIn?.inWholeMilliseconds?.toString() ?: "not yet"),
            "octavesCountAsCorrect" to preferences.octavesCountAsCorrect.toString(),
            "outputDelayMillis" to outputDelay.inWholeMilliseconds.toString(),
            "recognition" to when {
                microphone && usesModel -> "model"
                microphone && usesStrokeRecognition -> "strokes"
                else -> "classic"
            },
            "range" to "${settings.lowLimit}..${settings.highLimit}",
            "modelHopFrames" to (noteModel?.takeIf { microphone && usesModel }?.hopFrames?.toString() ?: ""),
            "chordDetectionParameters" to tuning.chordParameters(settings.mode.voices).toJson(),
        )
        if (!labelsSaved) savePlayedLabels(quiet = true)
        runSummary = null
        playedNotes.value = emptyList()
        feedback = feedback.restarted()

        val voices = settings.mode.voices
        val practice = PracticeRunner(
            scope, settings, setup.memory(), practiceOutput,
            input.onEach { message ->
                if (message.isNoteOn) showHeard(message.data1)
            },
            lateAnswerTolerance = lateAnswerTolerance,
            // Octave errors of the recognition are far more common than of the player.
            octavesCountAsCorrect = microphone && preferences.octavesCountAsCorrect,
            // The player hears each note only once the output has played it.
            reactionTime = PracticeRunner.REACTION_TIME + outputDelay,
            strokeAge = { strokeAge },
            extraLatency = { if (microphone) extraLatency() else Duration.ZERO },
            audibleDelay = { if (microphone) audibleDelay() else Duration.ZERO },
            maxSteps = optimizationSteps,
            onStep = { step ->
                recorder?.step(step)
                // The chords the player may be answering: the latest few (late answers).
                expectedChords.value = (expectedChords.value + listOf(step.given)).takeLast(EXPECTED_CHORDS)
            },
            onEvaluation = { recorder?.evaluation(it) },
            onAssignment = { recorder?.assignment(it) },
            beforeFirstStep = {
                // With the microphone: start once it delivers sound (a browser's first blocks are
                // silence), so the first note, which the player cannot be playing along with yet,
                // reaches it in full; the app learns its own sound's delay from that note.
                if (microphone) withTimeoutOrNull(MICROPHONE_WARM_UP_LIMIT) { microphoneLive.await() }
                if (microphone) delay(MICROPHONE_SETTLE)
            },
        )
        runner = practice
        running = true
        val stopsAtMistake = optimizationSteps != null && preferences.optimizationStopsAtMistake
        statusJob = scope.launch {
            practice.status.collect {
                status = it
                feedback = feedback.next(it, playedNotes.value.takeLast(voices))
                if (it.finished && runner === practice) stopPractice()
                // Stopped at once, while the player still knows what they played (optimization mode).
                if (stopsAtMistake && (it.lastResult?.correct == false || it.wrong > 0) && runner === practice) {
                    message = text(Res.string.msg_stopped_at_mistake)
                    stopPractice()
                }
            }
        }
        practice.start()
    }

    /** A key of the keyboard on the screen, during an exercise. */
    fun playKey(note: Int) {
        val practice = runner ?: return
        showHeard(note)
        practice.play(note)
    }

    /** Lights [note] up on the keyboard on the screen for a moment. */
    private fun showHeard(note: Int) {
        playedNotes.value = (playedNotes.value + note).takeLast(PLAYED_NOTES)
        scope.launch {
            heardJobs.remove(note)?.cancel()
            heardKeys = heardKeys + note
            heardJobs[note] = launch {
                delay(HEARD_KEY_MILLIS)
                heardKeys = heardKeys - note
            }
        }
    }

    /** Java: "Stop" in the run dialog. */
    fun stopPractice() {
        val practice = runner ?: return
        runner = null
        launchSafely { stopAndSave(practice) }
    }

    /** Stops a running exercise and writes everything to disk; call before the app exits. */
    suspend fun shutdown() {
        stopMicTest()
        stopMidiTest()
        val practice = runner
        runner = null
        if (practice != null) stopAndSave(practice) else saveNow()
    }

    private suspend fun stopAndSave(practice: PracticeRunner) {
        statusJob?.cancel()
        practice.stop()
        status = practice.status.value
        finishRecording()
        keepLearnedEcho()
        closePorts()
        refreshSetupState()
        saveNow()
        running = false
    }

    /** Opens the MIDI output (tuned) and the MIDI keyboard; returns the keyboard's messages. */
    private fun openMidiInput(): Flow<MidiMessage> {
        lateAnswerTolerance = settings.lateAnswerToleranceMillis.milliseconds // a key press arrives at once
        openOutput()
        val inputName = preferences.midiInputDevice?.takeIf { it in inputDevices } ?: defaultDevice(inputDevices)
            ?: throw UserError(text(Res.string.msg_no_midi_input))
        val input = ReconnectingMidiInput(inputName, services.midi::openInput)
        practiceInput = input
        closers += { input.close(); practiceInput = null }
        return input.messages
    }

    /** Only the keyboard on the screen answers, through [playKey]; no input to wait for. */
    private fun openScreenKeys(): Flow<MidiMessage> {
        lateAnswerTolerance = settings.lateAnswerToleranceMillis.milliseconds // a tap arrives at once
        openOutput()
        return flow { awaitCancellation() }
    }

    /** The microphone cannot hear the app: it plays into headphones, or (sight reading) not at all. */
    private val noOwnSound: Boolean get() = preferences.usesHeadphones || !preferences.playsGivenNotes

    /** Opens the MIDI output (tuned) and the microphone; returns the recognised notes as note-ons. */
    private fun openMicrophoneInput(settings: PracticeSettings): Flow<MidiMessage> {
        val audio = services.audio.open(preferences.audioInputDevice)
        closers += audio::close
        // Without headphones the microphone hears the app. If the app renders its synthesizer
        // itself, it knows what it played and removes that; until it can (and with other outputs),
        // input matching the app's current note is ignored.
        val parameters = tuning.detectionParameters
        val voices = settings.mode.voices
        val chordParameters = tuning.chordParameters(voices)
        val removeOwnSound = if (voices > 1) chordParameters.strokes.echoCancellation else parameters.echoCancellation
        val rendered = if (noOwnSound || !removeOwnSound) null else openRenderedOutput(audio.sampleRate)
        val midiOutput = rendered ?: openOutput()
        outputDelay = rendered?.bufferedTime ?: Duration.ZERO
        echoDelay = null
        val ownSound = if (noOwnSound) null else OwnSoundGate(midiOutput, outputDelay = outputDelay, extraLatency = ::extraLatency)
        gate = ownSound
        // The tolerance counts from the key stroke; the note arrives only once it is recognised.
        // A chord is decided only after its analysis window.
        val instrument = preferences.instrument.profile
        // A change of pitch without a new attack only counts where the app's own sound cannot be
        // taken for it: with headphones, or when the app renders (and so removes) its sound.
        val legato = instrument.sustained && (noOwnSound || rendered != null)
        // One recognition for notes and chords; the earlier one where a held instrument plays legato.
        usesStrokeRecognition = tuning.strokeRecognition && !legato
        // Or, for single notes, a learned model where the platform has one (debug builds); with
        // chords it is not as good yet.
        val model = if (tuning.modelRecognition && voices == 1) loadedModel() else null
        usesModel = model != null
        val strokeParameters = if (voices > 1) chordParameters else chordParameters.copy(strokes = parameters)
        // And the player hears the next note only once the output has played it.
        lateAnswerTolerance = settings.lateAnswerToleranceMillis.milliseconds + outputDelay + if (model != null) {
            NoteModelRecognizer.decisionDelayMillis(model).milliseconds
        } else if (usesStrokeRecognition) {
            val windowShift = instrument.chordWindowStartMillis?.let { it - strokeParameters.windowStartMillis } ?: 0
            (strokeParameters.windowEndMillis + windowShift).milliseconds +
                NoteTracker(audio.sampleRate, parameters = strokeParameters.strokes, instrument = instrument).detectionDelay
        } else if (voices > 1) {
            val windowShift = instrument.chordWindowStartMillis?.let { it - chordParameters.windowStartMillis } ?: 0
            (chordParameters.windowEndMillis + windowShift).milliseconds +
                NoteTracker(audio.sampleRate, parameters = chordParameters.strokes).detectionDelay
        } else {
            NoteTracker(audio.sampleRate, parameters = parameters, instrument = instrument).detectionDelay
        }
        val recording = if (tuning.recordMicrophone || tuning.optimizationMode) {
            val channels = if (rendered != null) listOf("microphone", "reference") else listOf("microphone")
            services.recordings?.let { SessionRecorder(it.create(), audio.sampleRate, channels) }
        } else {
            null
        }
        recorder = recording
        val live = CompletableDeferred<Unit>().also { microphoneLive = it }
        val silence = SilenceWatch(audio.sampleRate)
        val blocks = (if (rendered != null) audio.blocksWith(rendered::playedAudio) else audio.blocks.map { AudioBlock(it) })
            .onEach { block -> if (!live.isCompleted && block.microphone.any { it != 0f }) live.complete(Unit) }
            .onEach { block ->
                if (silence.verdict == SilenceWatch.Verdict.UNDECIDED && silence.process(block.microphone) == SilenceWatch.Verdict.SILENT) {
                    message = silentMicrophoneMessage()
                }
            }
        expectedChords.value = emptyList()
        fun DetectedChord.age() = ((sampleTime - onsetTime) * 1000 / audio.sampleRate).milliseconds
        // The app's sound cannot reach the microphone before the platform's output has played it.
        val shortestEchoDelay = (rendered?.outputLatency ?: Duration.ZERO) * SHORTEST_ECHO_SHARE
        // What an earlier run learned about this output in the room: removed from the first note on.
        val echoKey = rendered?.let { "${selectedOutputDevice()}@${audio.sampleRate}/${(it.outputLatency.inWholeMilliseconds + LATENCY_BUCKET_MILLIS / 2) / LATENCY_BUCKET_MILLIS}" }
        val echoStart = echoKey?.let { preferences.echoStates[it] }
        learnedEcho = null
        learnedEchoKey = echoKey
        val onEchoState: (EchoState) -> Unit = { learnedEcho = it }
        // On the recognizer's clock, which starts anew with every run.
        sentNotes.value = emptyList()
        microphoneSamples = 0L
        if (model != null) {
            val silent = noOwnSound
            return blocks
                .onEach { block ->
                    recording?.audio(listOfNotNull(block.microphone, block.reference))
                    microphoneSamples += block.microphone.size
                }
                // Recorded and counted as it arrives; what queued up while the model ran comes as one.
                .batchedWhileBusy()
                // The notes the app sent tell its echo apart (none reach the microphone through headphones).
                .modelStrokes(
                    audio.sampleRate, voices, settings.lowLimit..settings.highLimit, model,
                    appNotes = { if (silent) emptyList() else sentNotes.value }, onLevel = { microphoneLevel = it },
                )
                .onEach { recording?.detectedChord(it) }
                .flowOn(Dispatchers.Default)
                // The model failing on the way (a browser that cannot load it, say) is told, not hidden.
                .catch { if (it is CancellationException) throw it else message = text(Res.string.msg_model_failed, it.toUiText()) }
                .filter { chord ->
                    chord.ownSoundRemoved || (
                        if (voices > 1) ownSound?.acceptsChord(chord.notes, chord.age())
                        else ownSound?.accepts(MidiMessage.noteOn(chord.notes.first(), 100), chord.age())
                        ) ?: true
                }
                .onEach { strokeAge = it.age() }
                .flatMapConcat { chord -> chord.toNoteOns(voices).asFlow() }
                .onEach { recording?.accepted(it) }
        }
        if (usesStrokeRecognition) {
            return blocks
                .onEach { block -> recording?.audio(listOfNotNull(block.microphone, block.reference)) }
                .recognizedStrokes(
                    audio.sampleRate, voices, settings.lowLimit..settings.highLimit, preferences.referenceAHz,
                    strokeParameters, learnedTemplates, expected = { expectedChords.value },
                    onLevel = { microphoneLevel = it }, instrument = instrument, onEchoDelay = { echoDelay = it },
                    shortestEchoDelay = shortestEchoDelay, octavesCountAsCorrect = preferences.octavesCountAsCorrect,
                    echoStart = echoStart, onEchoState = onEchoState,
                )
                .onEach { recording?.detectedChord(it) }
                .flowOn(Dispatchers.Default)
                .filter { chord ->
                    chord.ownSoundRemoved || (
                        if (voices > 1) ownSound?.acceptsChord(chord.notes, chord.age())
                        else ownSound?.accepts(MidiMessage.noteOn(chord.notes.first(), 100), chord.age())
                        ) ?: true
                }
                // Evaluated where the exercise runs: the age goes with the note-ons that follow.
                .onEach { strokeAge = it.age() }
                .flatMapConcat { chord -> chord.toNoteOns(voices).asFlow() }
                .onEach { recording?.accepted(it) }
        }
        if (voices > 1) {
            return blocks
                .onEach { block -> recording?.audio(listOfNotNull(block.microphone, block.reference)) }
                .detectedChords(
                    audio.sampleRate, voices, settings.lowLimit..settings.highLimit, preferences.referenceAHz,
                    chordParameters, learnedTemplates, expected = { expectedChords.value },
                    onLevel = { microphoneLevel = it }, instrument = instrument, onEchoDelay = { echoDelay = it },
                    shortestEchoDelay = shortestEchoDelay, echoStart = echoStart, onEchoState = onEchoState,
                )
                .onEach { recording?.detectedChord(it) }
                .flowOn(Dispatchers.Default)
                .filter { chord -> chord.ownSoundRemoved || ownSound?.acceptsChord(chord.notes, chord.age()) ?: true }
                .onEach { strokeAge = it.age() }
                .flatMapConcat { chord -> chord.toNoteOns(voices).asFlow() }
                .onEach { recording?.accepted(it) }
        }
        return blocks
            .onEach { block -> recording?.audio(listOfNotNull(block.microphone, block.reference)) }
            .detectedNotes(
                audio.sampleRate, preferences.referenceAHz, onLevel = { microphoneLevel = it }, parameters = parameters,
                onEchoDelay = { echoDelay = it }, shortestEchoDelay = shortestEchoDelay, echoStart = echoStart, onEchoState = onEchoState,
                instrument = instrument, legato = legato,
                // An answer is a note of the exercise, give or take an octave (the recognition's error).
                plausible = settings.lowLimit - 12..settings.highLimit + 12,
            )
            .onEach { recording?.detected(it) }
            .flowOn(Dispatchers.Default)
            // Evaluated where the exercise runs, which is also where the gate sees the notes played.
            .filter { note -> note.midiNote in 0..127 && (note.ownSoundRemoved || ownSound?.accepts(note.toNoteOn()) ?: true) }
            .onEach { strokeAge = Duration.ZERO }
            .map { note -> note.toNoteOn() }
            .onEach { recording?.accepted(it) }
    }

    /** Writes the header and the log of a recorded session; the audio has stopped by now. */
    /** What the running exercise's echo estimate has learned lately (audio thread), and for which output. */
    @Volatile private var learnedEcho: EchoState? = null
    private var learnedEchoKey: String? = null

    /** Keeps what the last run learned about the app's sound for the next one with the same output. */
    private fun keepLearnedEcho() {
        val state = learnedEcho ?: return
        val key = learnedEchoKey ?: return
        learnedEcho = null
        updatePreferences { it.copy(echoStates = it.echoStates + (key to state)) }
    }

    private suspend fun finishRecording() {
        val recording = recorder ?: return
        recorder = null
        // Before the ports close: how the output fared (dropouts, lost alignment with the microphone).
        val diagnostics = (output as? RenderedOutputPort)?.diagnostics().orEmpty() + listOfNotNull(
            echoDelay?.let { "echoDelayMillis" to it.inWholeMilliseconds.toString() },
            (output as? RenderedOutputPort)?.let { "platformLatencyMillis" to it.outputLatency.inWholeMilliseconds.toString() },
        )
        runCatching { withContext(Dispatchers.Default) { recording.finish(recordingInfo + diagnostics) } }
            .onSuccess {
                message = text(Res.string.msg_recording_saved, recording.name)
                if (tuning.optimizationMode) {
                    runSummary = RunSummary(recording.name, recording.summary())
                    summaryRecording = recording
                    playedLabels = emptyMap()
                    labelsSaved = true
                }
            }
            .onFailure { message = text(Res.string.msg_recording_failed, it.toUiText()) }
    }

    /**
     * The app's own rendering of the chosen MIDI output, if it can do that (its own piano, or
     * Gervill on the desktop), so its sound can be removed from the microphone signal; null otherwise.
     */
    private fun openRenderedOutput(sampleRate: Int): RenderedOutputPort? {
        refreshDevices()
        val synth = services.renderedSynths.firstOrNull { it.deviceName == selectedOutputDevice() } ?: return null
        val port = runCatching { synth.open(sampleRate) }.getOrElse {
            message = text(Res.string.msg_own_sound_failed, it.toUiText())
            return null
        }
        output = port
        Tuning.messages(preferences.referenceAHz).forEach(port::send)
        return port
    }

    private fun selectedOutputDevice(): String? =
        preferences.midiOutputDevice?.takeIf { it in outputDevices } ?: defaultDevice(outputDevices)

    private fun openOutput(): MidiOutputPort {
        refreshDevices()
        val outputName = selectedOutputDevice() ?: throw UserError(text(Res.string.msg_no_midi_output))
        // Tuned again whenever the device comes back after dropping out.
        val port = ReconnectingMidiOutput(outputName, services.midi::openOutput) { opened -> Tuning.messages(preferences.referenceAHz).forEach(opened::send) }
        output = port
        return port
    }

    private fun closePorts() {
        closers.forEach { runCatching { it() } }
        closers.clear()
        output?.let { runCatching { it.close() } }
        output = null
        gate = null
    }

    // ------------------------------------------------------------ microphone test

    /** Opens the microphone and shows level and recognised notes in Preferences. */
    /**
     * True if the microphone may be used now. Otherwise asks the user (Android) and, if they
     * allow it, runs [retry] afterwards; false meanwhile.
     */
    private fun withMicrophoneAccess(retry: () -> Unit): Boolean {
        if (services.audio.hasAccess) return true
        launchSafely {
            if (services.audio.requestAccess()) {
                refreshDevices() // a browser names its microphones only now
                retry()
            } else {
                message = text(Res.string.msg_microphone_denied)
            }
        }
        return false
    }

    fun startMicTest() {
        if (running || micTesting) return
        if (!withMicrophoneAccess(::startMicTest)) return
        val audio = runCatching { services.audio.open(preferences.audioInputDevice) }.getOrElse {
            message = text(Res.string.msg_open_microphone_failed, it.toUiText())
            return
        }
        micTestPort = audio
        micTesting = true
        micTestNote = null
        micTestSilent = false
        val silence = SilenceWatch(audio.sampleRate, seconds = MIC_TEST_SILENCE_SECONDS)
        micTestJob = launchSafely {
            audio.blocks
                .onEach { micTestSilent = silence.process(it) == SilenceWatch.Verdict.SILENT }
                .detectNotes(
                    audio.sampleRate,
                    preferences.referenceAHz,
                    onNote = { micTestNote = it },
                    onLevel = { microphoneLevel = it },
                    parameters = tuning.detectionParameters,
                    instrument = preferences.instrument.profile,
                    legato = true, // nothing else sounds during the test
                )
                .flowOn(Dispatchers.Default)
                .collect()
        }
    }

    // ---------------------------------------------------------- piano calibration

    /** The note to play now while calibrating; null when not calibrating. */
    var calibrationTarget by mutableStateOf<Int?>(null)
        private set
    /** What the last stroke sounded like, if it was not the asked note. */
    var calibrationHeard by mutableStateOf<List<Int>?>(null)
        private set
    var calibrationProgress by mutableStateOf(0 to 0)
        private set
    var calibrating by mutableStateOf(false)
        private set
    private var calibrationJob: Job? = null
    private var calibrationPort: AudioInputPort? = null

    /**
     * Asks for each note of the current range in turn and learns its spectrum (headphones or not:
     * the app plays nothing meanwhile); saved when all notes are done.
     */
    fun startCalibration() {
        if (running || calibrating) return
        if (!withMicrophoneAccess(::startCalibration)) return
        stopMicTest()
        val audio = runCatching { services.audio.open(preferences.audioInputDevice) }.getOrElse {
            message = text(Res.string.msg_open_microphone_failed, it.toUiText())
            return
        }
        calibrationPort = audio
        val notes = (settings.lowLimit..settings.highLimit).toList()
        val calibration = PianoCalibration(
            audio.sampleRate, notes, preferences.referenceAHz, tuning.chordParameters(2), learnedTemplates,
        )
        calibrating = true
        calibrationTarget = calibration.target
        calibrationHeard = null
        calibrationProgress = 0 to calibration.total
        calibrationJob = launchSafely {
            try {
                audio.blocks
                    .map { block ->
                        calibration.process(block)
                        Triple(calibration.target, calibration.lastHeard, calibration.done)
                    }
                    .flowOn(Dispatchers.Default)
                    .collect { (target, heard, done) ->
                        microphoneLevel = calibration.level
                        calibrationTarget = target
                        calibrationHeard = heard
                        calibrationProgress = done to calibration.total
                        if (target == null) {
                            learnedTemplates = calibration.result()
                            repository.saveTemplates(learnedTemplates)
                            message = text(Res.string.msg_calibrated, learnedTemplates.notes.size)
                            throw CancellationException("done")
                        }
                    }
            } finally {
                closeCalibration()
            }
        }
    }

    fun stopCalibration() {
        calibrationJob?.cancel()
        closeCalibration()
    }

    private fun closeCalibration() {
        calibrating = false
        calibrationJob = null
        calibrationPort?.close()
        calibrationPort = null
        calibrationTarget = null
        calibrationHeard = null
        microphoneLevel = 0.0
    }

    /** Back to the piano model for the chord recognition. */
    fun forgetCalibration() = launchSafely {
        learnedTemplates = LearnedTemplates()
        repository.saveTemplates(learnedTemplates)
    }

    // --------------------------------------------------------------- MIDI test

    /** Opens the chosen MIDI devices and shows the keys played in Preferences. */
    fun startMidiTest() {
        if (running || midiTesting) return
        refreshDevices()
        val input = runCatching {
            val name = preferences.midiInputDevice?.takeIf { it in inputDevices } ?: defaultDevice(inputDevices)
                ?: throw UserError(text(Res.string.msg_no_midi_input))
            ReconnectingMidiInput(name, services.midi::openInput)
        }.getOrElse {
            message = text(Res.string.msg_open_midi_input_failed, it.toUiText())
            return
        }
        midiTestInput = input
        midiTesting = true
        midiTestNotes = emptyList()
        midiTestJob = launchSafely {
            input.messages.filter { it.isNoteOn }.collect { note ->
                midiTestNotes = (listOf(note) + midiTestNotes).take(MIDI_TEST_HISTORY)
            }
        }
    }

    fun stopMidiTest() {
        midiTestJob?.cancel()
        midiTestJob = null
        midiTestInput?.let { runCatching { it.close() } }
        midiTestInput = null
        midiTestOutput?.let { runCatching { it.close() } }
        midiTestOutput = null
        midiTesting = false
    }

    /** Plays A4 (with the current Kammerton A) on the MIDI output, to check the sound. */
    fun playTestNote() {
        if (running) return
        val output = midiTestOutput ?: runCatching {
            refreshDevices()
            val name = preferences.midiOutputDevice?.takeIf { it in outputDevices } ?: defaultDevice(outputDevices)
                ?: throw UserError(text(Res.string.msg_no_midi_output))
            services.midi.openOutput(name)
        }.getOrElse {
            message = text(Res.string.msg_open_midi_output_failed, it.toUiText())
            return
        }
        // Kept open while the test runs; otherwise closed again after the note.
        val keepOpen = midiTesting
        if (keepOpen) midiTestOutput = output
        launchSafely {
            try {
                Tuning.messages(preferences.referenceAHz).forEach(output::send)
                output.send(MidiMessage.noteOn(TEST_NOTE, settings.midiOutVelocity))
                delay(TEST_NOTE_MILLIS)
                output.send(MidiMessage.noteOff(TEST_NOTE))
            } finally {
                if (!keepOpen) runCatching { output.close() }
            }
        }
    }

    fun stopMicTest() {
        micTestJob?.cancel()
        micTestJob = null
        micTestPort?.close()
        micTestPort = null
        micTesting = false
        micTestSilent = false
        microphoneLevel = 0.0
    }

    // ------------------------------------------------------------- preferences

    /** The microphones have no names yet: a browser tells them only once the app may use one. */
    val microphoneNamesHidden: Boolean get() = audioInputDevices.isEmpty() && !services.audio.hasAccess

    private fun silentMicrophoneMessage(): UiText =
        preferences.audioInputDevice?.takeIf { it in audioInputDevices }
            ?.let { text(Res.string.msg_microphone_silent, it) }
            ?: text(Res.string.msg_microphone_silent_default)

    fun refreshDevices() {
        inputDevices = runCatching { services.midi.inputDevices() }.getOrDefault(emptyList())
        outputDevices = runCatching { services.midi.outputDevices() }.getOrDefault(emptyList())
        audioInputDevices = runCatching { services.audio.devices() }.getOrDefault(emptyList())
    }

    val canConnectBluetoothMidi: Boolean get() = services.bluetoothMidi != null

    /** Lets the user connect a Bluetooth MIDI device; once connected it is chosen like one plugged in. */
    fun connectBluetoothMidi() {
        val connector = services.bluetoothMidi ?: return
        if (running) return
        launchSafely {
            runCatching { connector.connect() }
                .onSuccess { onMidiDevicesChanged() }
                .onFailure { if (it is CancellationException) throw it else message = text(Res.string.msg_bluetooth_failed, it.toUiText()) }
        }
    }

    /** The synthesizers the app renders itself, whose sound it can remove from the microphone; null if none. */
    val ownSynthName: String? get() = services.renderedSynths.joinToString(" / ") { it.deviceName }.ifEmpty { null }

    /** The app's piano plays recorded samples (they are loaded when the app starts). */
    var pianoSampled by mutableStateOf(false)
        private set

    /** Sight reading needs notes to read: hiding them ends it. */
    fun setGivenNotes(notes: GivenNotes) = updatePreferences {
        it.copy(givenNotes = notes, playsGivenNotes = it.playsGivenNotes || notes == GivenNotes.HIDDEN)
    }

    /** Sight reading: the app plays nothing, the notes on the staff unless they are shown otherwise. */
    fun setSightReading(on: Boolean) = updatePreferences {
        it.copy(playsGivenNotes = !on, givenNotes = if (on && it.givenNotes == GivenNotes.HIDDEN) GivenNotes.STAFF else it.givenNotes)
    }

    fun setTheme(theme: ThemeMode) = updatePreferences { it.copy(theme = theme) }

    fun selectInputDevice(name: String) {
        val wasTesting = midiTesting
        stopMidiTest()
        updatePreferences { it.copy(midiInputDevice = name) }
        if (wasTesting) startMidiTest()
    }
    fun selectOutputDevice(name: String) {
        midiTestOutput?.let { runCatching { it.close() } }
        midiTestOutput = null
        updatePreferences { it.copy(midiOutputDevice = name) }
    }

    /** Java: Preferences → Kammerton A. Applies immediately to the output of a running exercise. */
    fun setReferenceA(hz: Double) {
        val clamped = hz.coerceIn(Tuning.MIN_A_HZ, Tuning.MAX_A_HZ)
        updatePreferences { it.copy(referenceAHz = clamped) }
        output?.let { port -> Tuning.messages(clamped).forEach(port::send) }
    }

    fun setInputSource(source: InputSource) {
        updatePreferences { it.copy(inputSource = source) }
        prepareModel()
    }
    fun setUsesHeadphones(uses: Boolean) = updatePreferences { it.copy(usesHeadphones = uses) }
    fun setInstrument(instrument: PlayerInstrument) = updatePreferences { it.copy(instrument = instrument) }
    fun setShowTransposed(show: Boolean) = updatePreferences { it.copy(showTransposed = show) }

    /**
     * How a (sounding) note is shown: its name, or, with [AppPreferences.showTransposed], the
     * note a player of the chosen transposing instrument reads for it.
     */
    fun noteName(midiNote: Int): String = NoteNames.displayName(shownNote(midiNote))

    /** The note as shown: as written for the player's instrument if they want that. */
    fun shownNote(midiNote: Int): Int = midiNote + if (preferences.showTransposed) preferences.instrument.transposition else 0
    fun setOctavesCountAsCorrect(on: Boolean) = updatePreferences { it.copy(octavesCountAsCorrect = on) }

    fun setStrokeRecognition(on: Boolean) = updatePreferences { it.copy(strokeRecognition = on) }
    fun setModelRecognition(on: Boolean) {
        updatePreferences { it.copy(modelRecognition = on) }
        prepareModel()
    }

    /** The learned model, opened once and kept: loading it takes a while (in a browser, seconds). */
    @Volatile private var noteModel: NoteModel? = null

    /** The learned model, opened now if it was not yet; null where there is none or it failed. */
    private fun loadedModel(): NoteModel? = noteModel ?: services.noteModel?.let { open ->
        runCatching { open() }.onFailure { message = text(Res.string.msg_model_failed, it.toUiText()) }.getOrNull()
    }?.also { noteModel = it }

    /**
     * Loads the learned model ahead, as soon as it would be used (chosen, and the microphone the
     * input), so the first exercise does not wait for it; lets it go when it would not.
     */
    private fun prepareModel() {
        val wanted = services.noteModel != null && tuning.modelRecognition && preferences.inputSource == InputSource.MICROPHONE
        if (wanted) {
            if (noteModel == null) launchSafely { withContext(Dispatchers.Default) { loadedModel() } }
        } else if (!running) {
            noteModel?.let { runCatching { it.close() } }
            noteModel = null
        }
    }

    /** Whether the platform can run a learned note recognizer (see [PlatformServices.noteModel]). */
    val hasNoteModel: Boolean get() = services.noteModel != null

    /** With the learned model: the notes the app sent lately, and how many microphone samples have come in. */
    private val sentNotes = MutableStateFlow<List<AppNote>>(emptyList())
    @Volatile private var microphoneSamples = 0L
    private var usesModel = false

    /** Whether the running exercise uses [io.github.jonnyfrick.musicbootcamp.core.pitch.StrokeRecognizer]. */
    private var usesStrokeRecognition = false
    fun setOptimizationMode(on: Boolean) = updatePreferences { it.copy(optimizationMode = on) }
    fun setOptimizationStopsAtMistake(on: Boolean) = updatePreferences { it.copy(optimizationStopsAtMistake = on) }
    fun setRecordMidiTruth(on: Boolean) = updatePreferences { it.copy(recordMidiTruth = on) }

    /** The MIDI keyboard whose key presses the running exercise logs as the truth, if any. */
    private var midiTruthDevice: String? = null

    /**
     * Optimization mode with the microphone: logs what the MIDI keyboard plays alongside, as the
     * truth the recognition is measured against; returns the device, or null (not wanted, no
     * keyboard, no recording). The exercise itself still listens to the microphone.
     */
    private fun openMidiTruth(): String? {
        val recording = recorder ?: return null
        if (!tuning.optimizationMode || !preferences.recordMidiTruth) return null
        val name = preferences.midiInputDevice?.takeIf { it in inputDevices } ?: defaultDevice(inputDevices) ?: run {
            message = text(Res.string.msg_no_midi_truth)
            return null
        }
        val input = runCatching { ReconnectingMidiInput(name, services.midi::openInput) }.getOrElse {
            message = text(Res.string.msg_open_midi_input_failed, it.toUiText())
            return null
        }
        val job = scope.launch { input.messages.filter { it.isNoteOn }.collect { recording.played(it) } }
        closers += { job.cancel(); input.close() }
        return name
    }
    fun setOptimizationSteps(steps: Int) =
        updatePreferences { it.copy(optimizationSteps = steps.coerceIn(OPTIMIZATION_STEP_RANGE)) }
    fun setDetectionParameters(parameters: DetectionParameters) = updatePreferences { it.copy(detectionParameters = parameters) }
    fun setChordDetectionParameters(voices: Int, parameters: ChordDetectionParameters) =
        updatePreferences { it.copy(chordDetectionParameters = it.chordDetectionParameters + (voices to parameters)) }
    fun setRecordMicrophone(record: Boolean) = updatePreferences { it.copy(recordMicrophone = record) }
    val recordingsLocation: String? get() = services.recordings?.location
    fun selectAudioInputDevice(name: String?) {
        val wasTesting = micTesting
        stopMicTest()
        updatePreferences { it.copy(audioInputDevice = name) }
        if (wasTesting) startMicTest()
    }

    /** The device used when none is chosen: the first one that is not Java's built-in sequencer. */
    fun defaultDevice(devices: List<String>): String? =
        devices.firstOrNull { it != JAVA_SEQUENCER } ?: devices.firstOrNull()

    fun dismissMessage() {
        message = null
    }

    // ----------------------------------------------------------------- helpers

    private fun updatePreferences(transform: (AppPreferences) -> AppPreferences) {
        preferences = transform(preferences)
        // One save at a time, each writing the newest preferences.
        val previous = preferencesJob
        preferencesJob = launchSafely {
            previous?.join()
            repository.savePreferences(preferences)
        }
    }

    /** Launches in [scope]; a failure becomes a message instead of crashing the app. */
    private fun launchSafely(block: suspend CoroutineScope.() -> Unit): Job = scope.launch {
        try {
            block()
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            message = text(Res.string.msg_error, e.toUiText())
        }
    }

    private fun refreshSetupState() {
        setupName = setup.name
        settings = setup.settings
        memoryCounts = setup.memory().countsByPriority()
        val range = settings.lowLimit..settings.highLimit
        sequencesOutsideRange = setup.memory().count { sequence -> sequence.any { element -> element.pitches.any { it !in range } } }
    }

    private fun scheduleSave() {
        saveJob?.cancel()
        saveJob = launchSafely {
            delay(AUTOSAVE_DELAY_MILLIS)
            repository.save(setup)
        }
    }

    private suspend fun saveNow() {
        saveJob?.cancel()
        runCatching { repository.save(setup) }.onFailure { message = text(Res.string.msg_save_failed, setup.name, it.toUiText()) }
    }

    private fun uniqueName(base: String): String {
        if (base !in setupNames) return base
        var i = 2
        while ("$base ($i)" in setupNames) i++
        return "$base ($i)"
    }

    companion object {
        const val DEFAULT_SETUP_NAME = "Default"
        private val MICROPHONE_WARM_UP_LIMIT = 2.seconds
        private val MICROPHONE_SETTLE = 300.milliseconds
        private const val MIC_TEST_SILENCE_SECONDS = 3.0
        private const val MIDI_TEST_HISTORY = 8
        private const val TEST_NOTE = 69 // A4
        private const val TEST_NOTE_MILLIS = 1000L
        private const val JAVA_SEQUENCER = "Real Time Sequencer"
        private const val AUTOSAVE_DELAY_MILLIS = 800L
    }
}

private const val EXPECTED_CHORDS = 3

/** The delay to the microphone the fixed time windows allow for (a phone's own loudspeaker measures about 0.28 s). */
private val USUAL_ECHO_DELAY = 300.milliseconds

/** The output latency a device's own loudspeaker has, which the fixed time windows allow for. */
private val USUAL_OUTPUT_LATENCY = 100.milliseconds

/**
 * The share of the reported output latency the app's echo takes at least: measured 1.5–3 times
 * as much on a phone, so a delay below is the player or chance (one in a phone's browser was).
 */
private const val SHORTEST_ECHO_SHARE = 0.9

/**
 * The reported output latency, rounded to steps this wide, tells outputs apart: it varies by a few
 * tens of milliseconds from run to run (a phone 90–125 ms), a Bluetooth loudspeaker adds 0.1 s or more.
 */
private const val LATENCY_BUCKET_MILLIS = 100

/** The notes sent kept for the learned model's echo test: more than its longest delay covers. */
private const val SENT_NOTES = 16

/** How many of the player's latest notes are kept for the keyboard on the practice screen. */
private const val PLAYED_NOTES = 8
private const val HEARD_KEY_MILLIS = 500L

/** What a run in optimization mode recorded, step by step. */
class RunSummary(val recording: String, val steps: List<StepSummary>)
