package io.github.jonnyfrick.musicbootcamp.platform

import io.github.jonnyfrick.musicbootcamp.core.midi.MidiMessage
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.emptyFlow
import kotlinx.coroutines.flow.flatMapLatest
import kotlin.concurrent.Volatile

/**
 * A MIDI input that survives its device dropping out for a moment (a loose USB cable): when the
 * device is back, [reconnect] opens it again, and [messages] goes on with the new port's.
 */
class ReconnectingMidiInput(val deviceName: String, private val open: (String) -> MidiInputPort) : MidiInputPort {
    private val port = MutableStateFlow<MidiInputPort?>(open(deviceName))

    @OptIn(ExperimentalCoroutinesApi::class)
    override val messages: Flow<MidiMessage> = port.flatMapLatest { it?.messages ?: emptyFlow() }

    /** Opens the device again; false if that failed (it stays without a port until the next try). */
    fun reconnect(): Boolean {
        port.value?.let { runCatching { it.close() } }
        port.value = null
        return runCatching { open(deviceName) }.onSuccess { port.value = it }.isSuccess
    }

    override fun close() {
        port.value?.let { runCatching { it.close() } }
        port.value = null
    }
}

/** A MIDI output that, like [ReconnectingMidiInput], opens its device again when it is back; [onOpened] then runs for the new port (tuning, say). */
class ReconnectingMidiOutput(
    val deviceName: String,
    private val open: (String) -> MidiOutputPort,
    private val onOpened: (MidiOutputPort) -> Unit = {},
) : MidiOutputPort {
    @Volatile private var port: MidiOutputPort? = open(deviceName).also(onOpened)

    // A message sent while the device is away is lost: there is nowhere for it to go.
    override fun send(message: MidiMessage) {
        port?.let { runCatching { it.send(message) } }
    }

    fun reconnect(): Boolean {
        port?.let { runCatching { it.close() } }
        port = null
        return runCatching { open(deviceName) }.onSuccess { port = it; onOpened(it) }.isSuccess
    }

    override fun close() {
        port?.let { runCatching { it.close() } }
        port = null
    }
}
