/** What the player says they played in one step, as [AppController.playedLabels] keeps it. */
internal sealed interface Played {
    data object AsGiven : Played
    data class Notes(val notes: List<Int>) : Played
    data object Nothing : Played
    data object Unknown : Played
}

internal fun playedOf(labels: Map<Int, List<Int>?>, step: Int): Played = when {
    step !in labels -> Played.AsGiven
    labels[step] == null -> Played.Unknown
    labels[step]!!.isEmpty() -> Played.Nothing
    else -> Played.Notes(labels.getValue(step)!!)
}

/**
 * Asks what the player really played in step [step] ([given] were the notes asked for): as given,
 * other notes (each moved by semitones from the given ones), nothing, or not sure what.
 */
@Composable
internal fun PlayedDialog(
    step: Int,
    given: List<Int>,
    current: Played,
    noteName: (Int) -> String,
    onDone: (Played) -> Unit,
) {
    var choice by remember { mutableStateOf(current) }
    var notes by remember { mutableStateOf((current as? Played.Notes)?.notes ?: given.distinct().sorted()) }
    AlertDialog(
        onDismissRequest = { onDone(current) },
        title = { Text(stringResource(Res.string.played_title, step)) },
        text = {
            Column(Modifier.selectableGroup().verticalScroll(rememberScrollState())) {
                @Composable
                fun option(played: Played, label: String) = ListItem(
                    headlineContent = { Text(label) },
                    leadingContent = { RadioButton(selected = choice::class == played::class, onClick = null) },
                    colors = itemColors(),
                    modifier = Modifier.selectable(selected = choice::class == played::class, role = Role.RadioButton) { choice = played },
                )
                option(Played.AsGiven, stringResource(Res.string.played_as_given) + ": " + given.joinToString(" ") { noteName(it) })
                option(Played.Notes(notes), stringResource(Res.string.played_other))
                if (choice is Played.Notes) {
                    notes.forEachIndexed { index, note ->
                        Row(
                            Modifier.padding(start = 56.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                        ) {
                            fun move(by: Int) {
                                notes = notes.toMutableList().also { it[index] = (note + by).coerceIn(0, 127) }
                                choice = Played.Notes(notes)
                            }
                            IconButton(onClick = { move(-1) }) { Icon(AppIcons.Remove, contentDescription = stringResource(Res.string.played_lower)) }
                            Text(noteName(note), style = MaterialTheme.typography.titleMedium, textAlign = TextAlign.Center, modifier = Modifier.width(72.dp))
                            IconButton(onClick = { move(1) }) { Icon(AppIcons.Add, contentDescription = stringResource(Res.string.played_higher)) }
                        }
                    }
                }
                option(Played.Nothing, stringResource(Res.string.played_nothing))
                option(Played.Unknown, stringResource(Res.string.played_unknown))
            }
        },
        confirmButton = {
            TextButton(onClick = { onDone(if (choice is Played.Notes) Played.Notes(notes) else choice) }) {
                Text(stringResource(Res.string.played_done))
            }
        },
    )
}
