package io.github.jonnyfrick.musicbootcamp.core.pitch

import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.buffer
import kotlinx.coroutines.flow.channelFlow
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.launch
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.cos
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min
import kotlin.math.pow
import kotlin.math.roundToInt
import kotlin.math.sin
import kotlin.math.sqrt

/**
 * A learned model that turns [WINDOW_SAMPLES] of audio at [SAMPLE_RATE] into, per frame of
 * [FRAME_SAMPLES] and piano key ([LOWEST_NOTE] up, [NOTES] keys), how likely a note sounds and
 * starts there: Spotify's Basic Pitch (https://github.com/spotify/basic-pitch, Apache-2.0), run
 * by the platform (ONNX Runtime on Android).
 */
interface NoteModel {
    /**
     * Note and onset likelihoods, [FRAMES] × [NOTES] each, for exactly [WINDOW_SAMPLES] samples;
     * may take a while (a browser runs it in a worker and waits for the answer).
     */
    suspend fun analyse(window: FloatArray): Pair<Array<FloatArray>, Array<FloatArray>>

    /** How often the model runs, in frames: as often as the platform affords (a quarter of a second on a phone; in a browser, what the device manages). */
    val hopFrames: Int get() = 21

    fun close()

    companion object {
        const val SAMPLE_RATE = 22_050
        const val FRAME_SAMPLES = 256
        const val WINDOW_SAMPLES = SAMPLE_RATE * 2 - FRAME_SAMPLES
        const val FRAMES = 172
        const val LOWEST_NOTE = 21
        const val NOTES = 88
    }
}

/** A note the app sent to its loudspeaker, at [sample] of the microphone's stream. */
data class AppNote(val sample: Long, val note: Int)

/**
 * Recognises strokes with a [NoteModel] as the microphone's audio arrives: the model runs on the
 * latest two seconds every [NoteModel.hopFrames] frames (a quarter of a second on a phone); a frame counts once it has
 * [CONTEXT_FRAMES] of audio after it. A note's onset (its peak above [onsetThreshold], the note
 * then sounding above [noteThreshold]) is a stroke's note; onsets within [GROUP_FRAMES] are one
 * stroke — its strongest note, or with chords the [voices] strongest. A repeated onset of a note
 * still ringing counts only if as strong as [retrigger] (the model fires again on a decaying piano
 * note), except the exercise's first note, which the player knows beforehand. An onset of a note the app sent ([appNotes]), or of its octave, that long before as its
 * sound takes to reach the microphone is the app's echo: that delay is found where the notes sent
 * line up best with the microphone's onsets; until then, the first onset of a note the app sent
 * within [MAX_DELAY_FRAMES] is (a second one is the player, answering quickly).
 */
class NoteModelRecognizer(
    private val sampleRate: Int,
    private val voices: Int,
    range: IntRange,
    private val model: NoteModel,
    private val appNotes: () -> List<AppNote> = { emptyList() },
    // 0.6: weaker onsets were mostly a soft-attack note reported twice or a phantom low note
    // (synthetic runs: 91 → 51 mistakes over 15 scenarios; the phone's: 13 fewer, as many hits).
    private val onsetThreshold: Float = 0.6f,
    private val noteThreshold: Float = 0.3f,
    private val retrigger: Float = 0.8f,
    // A note the app just sent is expected: the model strikes low notes weakly (0.3 to 0.6) though
    // it hears them clearly, so one onset of it counts from here on, once the echo has passed.
    private val expectedThreshold: Float = 0.4f,
    // In chords the other voice's onset can pass for this one's (two-voice runs: more wrong notes).
    // 1.6: the middle of 1.2 to 2.5, where the synthetic runs do not change at all.
    private val expectedRise: Float = 1.6f,
) {
    private val plausible = range.first - 12..range.last + 12
    private val resampler = Resampler(sampleRate, NoteModel.SAMPLE_RATE)
    // Room for a window ending anywhere in the latest batch (see [process]).
    private val audio = FloatArray(2 * NoteModel.WINDOW_SAMPLES)
    private var resampled = 0L
    // What the app played, in step with [audio]; null until the platform gives it.
    private var played: FloatArray? = null
    private var referenceResampler: Resampler? = null
    private var playedSamples = 0L
    private val hop = model.hopFrames
    // Windows end where their start lies on the frame grid, so their frames are the stream's.
    private var nextRun = hop.toLong() * NoteModel.FRAME_SAMPLES + NoteModel.WINDOW_SAMPLES % NoteModel.FRAME_SAMPLES
    private var microphoneSamples = 0L

    // Frames from the start, kept for a while: note and onset rows, and what was decided up to where.
    private val notes = FrameHistory()
    private val onsets = FrameHistory()
    private var final = 0L // frames before this one are final
    // Onsets before this frame are looked at. Not the very first: where the window still holds the
    // silence before the stream began, the step to the room's sound looks like a stroke.
    private var picked = START_FRAMES.toLong()
    private val lastOnset = IntArray(NoteModel.NOTES) { Int.MIN_VALUE / 2 }
    private class Onset(val frame: Long, val note: Int, val strength: Float)
    private val group = mutableListOf<Onset>()

    private var delayFrom = -1

    /** Frames from a note sent to its echo's onset in the microphone, once found. */
    var delayFrames: Int? = null
        private set

    /**
     * Feeds microphone samples (mono, -1..1); returns the strokes decided in them. Several hops at
     * once (the audio queued up while the model took longer than a hop): the model runs on the
     * latest window that still covers every frame not yet final, so a slow device catches up
     * instead of falling further behind. [reference] is what the app played in the same time.
     */
    suspend fun process(samples: FloatArray, reference: FloatArray? = null): List<DetectedChord> {
        microphoneSamples += samples.size
        if (reference != null) {
            val ring = played ?: FloatArray(audio.size).also { played = it }
            val resample = referenceResampler ?: Resampler(sampleRate, NoteModel.SAMPLE_RATE).also { referenceResampler = it }
            for (sample in resample.process(reference)) ring[(playedSamples++ % ring.size).toInt()] = sample
        }
        val fresh = resampler.process(samples)
        for (sample in fresh) {
            audio[(resampled % audio.size).toInt()] = sample
            resampled++
        }
        val found = mutableListOf<DetectedChord>()
        val hopSamples = hop * NoteModel.FRAME_SAMPLES
        while (resampled >= nextRun) {
            while (resampled >= nextRun + hopSamples && covers(nextRun + hopSamples)) nextRun += hopSamples
            run(nextRun)
            nextRun += hopSamples
            found += pick()
        }
        return found
    }

    /** Whether the window ending at [end] leaves no frame out between the final ones and its own. */
    private fun covers(end: Long): Boolean =
        (end - NoteModel.WINDOW_SAMPLES).floorDiv(NoteModel.FRAME_SAMPLES.toLong()) + CONTEXT_FRAMES <= max(final, 0L)

    /** The model on the window ending at [end] (resampled samples); its frames with enough after them become final. */
    private suspend fun run(end: Long) {
        val start = end - NoteModel.WINDOW_SAMPLES
        val window = FloatArray(NoteModel.WINDOW_SAMPLES) { i ->
            val position = start + i
            if (position < 0 || position < resampled - audio.size) 0f else audio[(position % audio.size).toInt()]
        }
        val (note, onset) = model.analyse(window)
        // Frame i of the window is frame start / FRAME_SAMPLES + i of the stream (start lies on the grid).
        val first = start.floorDiv(NoteModel.FRAME_SAMPLES.toLong())
        val lastFinal = first + note.size - 1 - CONTEXT_FRAMES
        for (frame in maxOf(final, first + CONTEXT_FRAMES, 0L)..lastFinal) {
            val i = (frame - first).toInt()
            if (i !in note.indices) continue
            notes[frame] = note[i]
            onsets[frame] = onset[i]
        }
        final = max(final, lastFinal + 1)
    }

    /** Looks at the onsets of the frames that have enough final frames after them. */
    private fun pick(): List<DetectedChord> {
        val found = mutableListOf<DetectedChord>()
        val sent = appNotes().map { (frameOfMicrophone(it.sample)) to it.note }
        // Measured again as more notes are heard (the first few may mislead it).
        if (sent.size != delayFrom) {
            delayFrom = sent.size
            findDelay(sent)?.let { delayFrames = it }
        }
        val until = final - LOOK_AHEAD_FRAMES
        while (picked < until) {
            val t = picked++
            val row = onsets[t] ?: continue
            for (p in 0 until NoteModel.NOTES) {
                val note = p + NoteModel.LOWEST_NOTE
                val a = row[p]
                if (a < min(onsetThreshold, expectedThreshold) || note !in plausible) continue
                val expected = voices == 1 && a < retrigger && isExpected(t, note, sent)
                if (a < onsetThreshold && !expected) continue
                if ((t - 2..t + 2).any { it != t && (onsets[it]?.get(p) ?: 0f) > a }) continue
                if ((t until t + LOOK_AHEAD_FRAMES).maxOf { notes[it]?.get(p) ?: 0f } < noteThreshold) continue
                val last = lastOnset[p].toLong()
                val ringing = t - last <= RETRIGGER_FRAMES && (last until t).all { (notes[it]?.get(p) ?: 0f) >= noteThreshold / 2 }
                lastOnset[p] = t.toInt()
                val restruck = ringing && a < retrigger
                // The player answering while the app's note still rings (at a brisk tempo, the rule): a
                // full onset is enough then, as for a weak one where it does not ring (weaker ones there
                // were the app's own note).
                if (restruck && !(expected && a >= onsetThreshold) && !mayAnswerStart(t, note, sent)) continue
                if (isEcho(t, note, sent)) continue
                if (sent.firstOrNull()?.second == note) startAnswered = true
                sent.lastOrNull { (at, played) -> played == note && t - at in 0..EXPECTED_FRAMES }?.let { answered += it.first }
                if (group.isNotEmpty() && t - group.first().frame > GROUP_FRAMES) found += decideGroup()
                group += Onset(t, note, a)
            }
            if (group.isNotEmpty() && t - group.first().frame > GROUP_FRAMES) found += decideGroup()
        }
        return found
    }

    private fun decideGroup(): DetectedChord {
        val strongest = group.sortedByDescending { it.strength }
        val chord = strongest.map { it.note }.distinct().take(voices).sorted()
        val onset = microphoneSampleOf(group.first().frame)
        val runnerUp = strongest.firstOrNull { it.note !in chord }
        group.clear()
        return DetectedChord(
            chord, microphoneSamples, onset, ownSoundRemoved = delayFrames != null,
            RecognizedChord(chord, -strongest.first().strength.toDouble(), runnerUp?.let { listOf(it.note) }, runnerUp?.let { -it.strength.toDouble() }, emptyList()),
        )
    }

    private fun isEcho(frame: Long, note: Int, sent: List<Pair<Long, Int>>): Boolean {
        val delay = delayFrames
        if (delay != null) return sent.any { (at, played) -> (note - played) in OCTAVE_ECHOES && frame - at - delay in -ECHO_FRAMES..ECHO_FRAMES }
        // Delay not known yet: a note sent explains only its first onset (each octave once).
        val echoOf = sent.firstOrNull { (at, played) -> (note - played) in OCTAVE_ECHOES && frame - at in 0..MAX_DELAY_FRAMES.toLong() && (at to note) !in echoed }
            ?: return false
        echoed += echoOf.first to note
        echoed.removeAll { (at, _) -> frame - at > MAX_DELAY_FRAMES }
        return true
    }

    /**
     * The exercise's first note is known beforehand: a player may strike it while the app's still
     * rings, so there it needs no more than any onset (the echo itself is still told apart).
     */
    private fun mayAnswerStart(frame: Long, note: Int, sent: List<Pair<Long, Int>>): Boolean {
        if (startAnswered) return false
        val (at, start) = sent.firstOrNull() ?: return false
        return note == start && frame - at in 0..START_ANSWER_FRAMES
    }

    /**
     * Is [note] one the app sent lately and nothing has answered yet? Only past its echo, as nobody
     * answers sooner, only while it sounds on strongly, and only where it is louder than the app's
     * sound explains ([rise]): the app's note fading makes such onsets too, which must not answer for a
     * player who played nothing, while a soft wind note may never get louder and only stay as the piano fades.
     */
    private fun isExpected(frame: Long, note: Int, sent: List<Pair<Long, Int>>): Boolean {
        val (at, _) = sent.lastOrNull { (at, played) -> played == note && frame - at in 0..EXPECTED_FRAMES } ?: return false
        if (at in answered || frame - at < (delayFrames ?: USUAL_DELAY_FRAMES) + MIN_ANSWER_FRAMES) return false
        if ((frame until frame + LOOK_AHEAD_FRAMES).maxOf { notes[it]?.get(note - NoteModel.LOWEST_NOTE) ?: 0f } < EXPECTED_NOTE) return false
        return rise(frame, note) >= expectedRise
    }

    /**
     * How much louder [note] got at [frame] than the app's sound explains: each of its partials in
     * the microphone before, changed as much as the same partial changed in what the app played
     * (the room and the loudspeaker cancel out, so nothing needs learning), against the partials
     * after. Without the app's sound at hand, how much louder the microphone got.
     */
    private fun rise(frame: Long, note: Int): Float {
        val ring = played ?: return (level(frame, frame + RISE_FRAMES) / level(frame - RISE_FRAMES - 2, frame - 2)).pow(2)
        val delay = delayFrames ?: USUAL_DELAY_FRAMES
        val frequency = 440.0 * 2.0.pow((note - 69) / 12.0)
        var after = 0.0
        var explained = 0.0
        for (partial in 1..PARTIALS) {
            val f = frequency * partial
            if (f >= NoteModel.SAMPLE_RATE / 2) break
            val before = power(audio, resampled, frame - RISE_FRAMES - 2, f)
            val playedBefore = power(ring, playedSamples, frame - delay - RISE_FRAMES - 2, f)
            val playedAfter = power(ring, playedSamples, frame - delay, f)
            after += power(audio, resampled, frame, f)
            explained += before * (playedAfter + TINY) / (playedBefore + TINY)
        }
        return ((after + TINY) / (explained + TINY)).toFloat()
    }

    /** The power at [frequency] in [RISE_FRAMES] from [frame] on (Hann window), of a ring holding [count] samples so far. */
    private fun power(ring: FloatArray, count: Long, frame: Long, frequency: Double): Double {
        val size = RISE_FRAMES * NoteModel.FRAME_SAMPLES
        val start = frame * NoteModel.FRAME_SAMPLES
        val step = 2 * cos(2 * PI * frequency / NoteModel.SAMPLE_RATE)
        var last = 0.0
        var previous = 0.0
        for (i in 0 until size) {
            val position = start + i
            val sample = if (position < 0 || position >= count || position < count - ring.size) 0f else ring[(position % ring.size).toInt()]
            val value = sample * (1 - cos(2 * PI * i / size)) / 2 + step * last - previous
            previous = last
            last = value
        }
        return (last * last + previous * previous - step * last * previous) / (size.toDouble() * size)
    }

    /** The audio's root mean square between two frames. */
    private fun level(from: Long, until: Long): Float {
        val range = maxOf(from * NoteModel.FRAME_SAMPLES, resampled - audio.size, 0L) until minOf(until * NoteModel.FRAME_SAMPLES, resampled)
        if (range.first > range.last) return 0f
        return sqrt(range.sumOf { position -> audio[(position % audio.size).toInt()].toDouble().pow(2) } / (range.last - range.first + 1)).toFloat()
    }

    /** The frames of the notes sent that an onset already answered. */
    private val answered = mutableSetOf<Long>()

    /** Once the first note was answered at all, its later onsets (a violin's vibrato) are no more answers than any other's. */
    private var startAnswered = false

    /** Before the delay is known: the notes sent (frame, onset's note) whose echo was heard. */
    private val echoed = mutableSetOf<Pair<Long, Int>>()

    /** The lag at which the notes sent line up best with the microphone's onsets; null until [MIN_SENT_FOR_DELAY] were heard. */
    private fun findDelay(sent: List<Pair<Long, Int>>): Int? {
        val heard = sent.filter { (at, _) -> at + MAX_DELAY_FRAMES + 1 < final }
        if (heard.size < MIN_SENT_FOR_DELAY) return null
        // The loudspeaker may give a note octaves off (a phone's hardly plays a low fundamental).
        fun onsetAt(frame: Long, note: Int) = OCTAVE_ECHOES.maxOf { o -> onsets[frame]?.getOrNull(note + o - NoteModel.LOWEST_NOTE) ?: 0f }
        // Only each note's first onset after it was sent: the echo comes before any answer, and a
        // player answering as regularly would otherwise line up just as well.
        val scores = DoubleArray(MAX_DELAY_FRAMES + 1)
        for ((at, note) in heard.takeLast(DELAY_NOTES)) {
            val first = (0..MAX_DELAY_FRAMES).firstOrNull { lag -> onsetAt(at + lag, note) >= onsetThreshold } ?: continue
            for (lag in first - 1..first + 1) if (lag in scores.indices) scores[lag] += onsetAt(at + first, note).toDouble()
        }
        val best = scores.indices.maxBy { scores[it] }
        // Clear enough: most of the notes sent show an onset there.
        return best.takeIf { scores[it] >= MIN_ECHO_SHARE * min(heard.size, DELAY_NOTES) }
    }

    private fun frameOfMicrophone(sample: Long) = (sample.toDouble() * NoteModel.SAMPLE_RATE / sampleRate / NoteModel.FRAME_SAMPLES).roundToInt().toLong()
    private fun microphoneSampleOf(frame: Long) = (frame.toDouble() * NoteModel.FRAME_SAMPLES * sampleRate / NoteModel.SAMPLE_RATE).toLong()

    fun close() = model.close()

    /** Rows by frame for the last [HISTORY_FRAMES] frames. */
    private class FrameHistory {
        private val rows = arrayOfNulls<FloatArray>(HISTORY_FRAMES)
        private val frames = LongArray(HISTORY_FRAMES) { -1 }
        operator fun get(frame: Long): FloatArray? {
            if (frame < 0) return null
            val slot = (frame % HISTORY_FRAMES).toInt()
            return rows[slot].takeIf { frames[slot] == frame }
        }
        operator fun set(frame: Long, row: FloatArray) {
            val slot = (frame % HISTORY_FRAMES).toInt()
            rows[slot] = row
            frames[slot] = frame
        }
    }

    companion object {
        /** At the latest this long after a stroke began, it is decided with [model]: the hop, the context a frame needs, the look-ahead, the grouping. */
        fun decisionDelayMillis(model: NoteModel): Long =
            (model.hopFrames + CONTEXT_FRAMES + LOOK_AHEAD_FRAMES + GROUP_FRAMES) * NoteModel.FRAME_SAMPLES * 1000L / NoteModel.SAMPLE_RATE

        private const val START_FRAMES = 43 // ≈ 0.5 s
        private const val CONTEXT_FRAMES = 15 // the model's frames near a window's ends are less sure
        private const val LOOK_AHEAD_FRAMES = 6
        private const val GROUP_FRAMES = 8
        private const val RETRIGGER_FRAMES = 60
        private const val ECHO_FRAMES = 6 // an echo's onset varies by note (its attack) by about this much around the delay
        private const val MAX_DELAY_FRAMES = 78 // ≈ 0.9 s
        private const val START_ANSWER_FRAMES = 172 // ≈ 2 s
        private const val EXPECTED_FRAMES = 172 // ≈ 2 s
        private const val MIN_ANSWER_FRAMES = 25 // ≈ 0.3 s
        private const val USUAL_DELAY_FRAMES = 30 // ≈ 0.35 s, until the delay is measured
        private const val EXPECTED_NOTE = 0.6f
        private const val RISE_FRAMES = 6 // ≈ 70 ms
        private const val PARTIALS = 6
        private const val TINY = 1e-10 // keeps silence from dividing by nothing
        private const val HISTORY_FRAMES = 1024 // ≈ 12 s
        private const val MIN_SENT_FOR_DELAY = 4
        private const val DELAY_NOTES = 12 // the latest notes sent the delay is measured on
        private const val MIN_ECHO_SHARE = 0.25
        // A phone's loudspeaker can make a low note's upper partials louder than its fundamental.
        private val OCTAVE_ECHOES = listOf(0, 12, 24, -12)
    }
}

/** Band-limited resampling as the audio arrives (for [NoteModel], which wants 22 050 Hz): windowed sinc (Blackman), cut off just below the lower Nyquist frequency. */
class Resampler(private val from: Int, private val to: Int) {
    private val ratio = to.toDouble() / from
    private val cutoff = 0.95 * min(1.0, ratio)
    private val halfWidth = (16 / min(1.0, ratio)).toInt()
    private val kernelScale = cutoff
    private val history = FloatArray(4 * halfWidth + 8192)
    private var received = 0L // input samples so far
    private var produced = 0L // output samples so far

    // Output sample p lies at input position p · from / to: a whole part and one of [phases]
    // fractions (147 for 48 kHz to 22 050 Hz), so the filter is worked out once per fraction.
    private val divisor = gcd(from, to)
    private val step = (from / divisor).toLong()
    private val phases = to / divisor
    private val kernels: Array<DoubleArray>? = if (phases <= MAX_PHASES) Array(phases) { phase -> kernel(phase.toDouble() / phases) } else null

    /** The filter's weights for the inputs from halfWidth before to halfWidth after the output's whole position, [fraction] past it. */
    private fun kernel(fraction: Double) = DoubleArray(2 * halfWidth + 1) { k ->
        val x = k - halfWidth - fraction
        val sinc = if (abs(x) < 1e-9) 1.0 else sin(PI * cutoff * x) / (PI * cutoff * x)
        val position = (x + halfWidth) / (2.0 * halfWidth)
        if (position < 0 || position > 1) 0.0
        else kernelScale * sinc * (0.42 - 0.5 * cos(2 * PI * position) + 0.08 * cos(4 * PI * position))
    }

    fun process(input: FloatArray): FloatArray {
        if (from == to) return input.copyOf()
        val out = mutableListOf<Float>()
        // In pieces the history holds with room to spare, however much arrives at once.
        var offset = 0
        while (offset < input.size) {
            val length = min(PIECE, input.size - offset)
            for (i in offset until offset + length) {
                history[(received % history.size).toInt()] = input[i]
                received++
            }
            offset += length
            produce(out)
        }
        return out.toFloatArray()
    }

    private fun produce(out: MutableList<Float>) {
        while (true) {
            val position = produced * step
            val whole = position / phases
            if (whole + halfWidth >= received) break // needs input not there yet
            val weights = kernels?.get((position % phases).toInt()) ?: kernel((position % phases).toDouble() / phases)
            val first = whole - halfWidth
            var sum = 0.0
            for (k in weights.indices) {
                val i = first + k
                if (i < 0 || i < received - history.size) continue
                sum += history[(i % history.size).toInt()] * weights[k]
            }
            out += sum.toFloat()
            produced++
        }
    }

    private companion object {
        const val PIECE = 4096
        const val MAX_PHASES = 4096

        tailrec fun gcd(a: Int, b: Int): Int = if (b == 0) a else gcd(b, a % b)
    }
}

/**
 * The blocks as they come, except that those queued up while the collector was busy come as one:
 * a recognition slower than the audio for a while ([NoteModelRecognizer.process]) catches up at
 * once instead of lagging ever further behind. Everything before this runs as the audio arrives.
 */
fun Flow<AudioBlock>.batchedWhileBusy(): Flow<AudioBlock> = channelFlow {
    val queued = Channel<AudioBlock>(Channel.UNLIMITED)
    launch {
        try {
            collect { queued.send(it) }
        } finally {
            queued.close()
        }
    }
    for (first in queued) {
        val batch = mutableListOf(first)
        while (true) batch += queued.tryReceive().getOrNull() ?: break
        send(if (batch.size == 1) first else batch.merged())
    }
}.buffer(Channel.RENDEZVOUS)

private fun List<AudioBlock>.merged(): AudioBlock {
    val microphone = FloatArray(sumOf { it.microphone.size })
    var at = 0
    for (block in this) block.microphone.copyInto(microphone, at).also { at += block.microphone.size }
    val reference = if (all { it.reference != null }) FloatArray(microphone.size).also { out ->
        var position = 0
        for (block in this) block.reference!!.copyInto(out, position).also { position += block.microphone.size }
    } else null
    return AudioBlock(microphone, reference)
}

/**
 * Strokes recognised by [NoteModelRecognizer] as the microphone's audio arrives. The [model] stays
 * open afterwards: the caller keeps it for the next run (loading it takes a while).
 */
fun Flow<AudioBlock>.modelStrokes(
    sampleRate: Int,
    voices: Int,
    range: IntRange,
    model: NoteModel,
    appNotes: () -> List<AppNote>,
    onLevel: (Double) -> Unit = {},
): Flow<DetectedChord> = flow {
    val recognizer = NoteModelRecognizer(sampleRate, voices, range, model, appNotes)
    collect { block ->
        val chords = recognizer.process(block.microphone, block.reference)
        onLevel(kotlin.math.sqrt(block.microphone.sumOf { (it * it).toDouble() } / max(1, block.microphone.size)))
        chords.forEach { emit(it) }
    }
}
