package io.github.jonnyfrick.musicbootcamp

import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.withFrameNanos
import androidx.compose.ui.ExperimentalComposeUiApi
import androidx.compose.ui.window.ComposeViewport
import io.github.jonnyfrick.musicbootcamp.ui.App
import io.github.jonnyfrick.musicbootcamp.web.webServices

@OptIn(ExperimentalComposeUiApi::class)
fun main() {
    // The page's start log (index.html): the program runs, then its first frame is drawn.
    startPhase("app")
    val services = webServices()
    ComposeViewport {
        LaunchedEffect(Unit) {
            withFrameNanos { }
            startPhase("ready")
        }
        App(services)
    }
}

private fun startPhase(phase: String): Unit = js("{ if (typeof window.mbcPhase === 'function') window.mbcPhase(phase); }")
