/**
 * Services of the web app (JavaScript and WebAssembly alike): setups in the browser's local
 * storage, MIDI through the Web MIDI API (Chromium browsers and Firefox), the microphone through
 * `getUserMedia`, and the app's own piano ([Instruments.piano]) through the Web Audio API as sound output.
 *
 * The browser side is a handful of small JavaScript functions (below) that keep their objects in
 * `globalThis.__mbc` and exchange only numbers, strings and callbacks with Kotlin, which is what
 * both targets can pass. Audio crosses as strings ([PackedAudio]), a block per call: one call per
 * sample kept the main thread too busy on a phone.
 */
fun webServices(): PlatformServices {
    initState()
    val piano = WebPianoSynth()
    return PlatformServices(
        midi = SynthMidiBackend(WebMidiBackend(), piano),
        documents = LocalStorageDocumentStore(),
        legacyFiles = null,
        audio = WebAudioInput(),
        audioDecoder = ::decodeInBrowser,
        recordings = DownloadRecordingStore(),
        // TEMPORARY: the developer tools (Settings → Recognition: recording, optimization mode,
        // detection parameters) are on for everyone on the web, to tune the recognition in
        // browsers. Set back to false when that is done (see MIGRATION.md, "Open points").
        debugTools = true,
        renderedSynths = listOf(piano),
        // Basic Pitch in a worker, loaded only once an exercise with the microphone uses it.
        noteModel = { WebNoteModel() },
    )
}

/**
 * Decodes a sound file with the browser's own decoder (native code, off the main thread), which
 * is much faster than the common Kotlin one running as WebAssembly; that one is the fallback.
 * Samples cross into Kotlin packed in a string, two orders of magnitude cheaper than one call
 * per sample, at 15 bits (a code unit per sample, kept below the surrogate range).
 */
private suspend fun decodeInBrowser(bytes: ByteArray): DecodedAudio {
    val packed = CharArray(bytes.size) { (bytes[it].toInt() and 0xFF).toChar() }.concatToString()
    val result = suspendCoroutine { continuation -> decodeAudio(packed) { rate, samples -> continuation.resume(rate to samples) } }
    val (rate, samples) = result
    if (rate <= 0 || samples == null) return decodeFlac(bytes)
    return DecodedAudio(rate, FloatArray(samples.length) { (samples[it].code - PACKED_ZERO) / PACKED_SCALE })
}

private const val PACKED_ZERO = 16384
private const val PACKED_SCALE = 16383f

/** One local-storage entry per document. Local storage is synchronous and holds a few megabytes. */
private class LocalStorageDocumentStore : DocumentStore {
    override suspend fun read(name: String): String? = storageGet(PREFIX + name)

    override suspend fun write(name: String, content: String) = storageSet(PREFIX + name, content)

    override suspend fun delete(name: String) = storageRemove(PREFIX + name)

    override suspend fun list(): List<String> =
        storageKeys(PREFIX).split('\n').filter { it.isNotEmpty() }.map { it.removePrefix(PREFIX) }.sorted()

    private companion object {
        const val PREFIX = "musicbootcamp/"
    }
}

/** The app's own piano on the loudspeaker; rendered by the app, so its sound can be removed from the microphone signal. */
private class WebPianoSynth : RenderedSynth {
    override val deviceName = BUILT_IN_PIANO

    // The browser decides the sample rate; microphone and synthesizer share one audio context.
    override fun open(sampleRate: Int): RenderedOutputPort = WebSynthPort()
}

/**
 * The piano on the browser's audio thread, where the main thread's being busy cannot make it tear:
 * the "mbc-player" worklet plays the sampled piano's voices itself, told what to play by a
 * [RemoteSampler] here (the recordings are handed over once). Before the samples are decoded (the
 * first exercise right after the page opened), the synthetic piano is rendered here instead and
 * queued [AHEAD_SECONDS] ahead, as all of it used to be. What the player plays reaches the
 * microphone's worklet as its second input, so the reference comes with the microphone's blocks
 * ([WebAudioPort.blocksWith]).
 */
private class WebSynthPort : RenderedOutputPort {
    private val sampleRate = audioSampleRate()
    private val samples = Instruments.pianoSamples
    private var player = 0
    private val synth: SoftwareSynth = samples?.let { RemoteSampler(it, sampleRate, WorkletVoices { player }) } ?: Instruments.piano(sampleRate)
    private var block = FloatArray(CHUNK_FRAMES)
    private var followed = 0L
    private var scratch = FloatArray(0)

    init {
        player = if (samples != null) {
            uploadPiano(samples)
            playerStart(ahead = 0, chunk = 0, render = { "" }, onPlayed = ::follow)
        } else {
            playerStart(
                ahead = (AHEAD_SECONDS * sampleRate).toInt(),
                chunk = CHUNK_FRAMES,
                render = {
                    synth.render(block)
                    PackedAudio.pack(block)
                },
                onPlayed = {},
            )
        }
    }

    /** The remote sampler follows its voices along as far as the worklet has played. */
    private fun follow(played: Double) {
        val frames = (played.toLong() - followed).toInt().coerceIn(0, MAX_FOLLOW_FRAMES)
        followed = played.toLong()
        if (frames == 0) return
        if (scratch.size < frames) scratch = FloatArray(frames)
        synth.render(scratch, 0, frames)
    }

    override fun send(message: MidiMessage) = synth.send(message)

    override val bufferedTime: Duration = if (samples != null) MESSAGE_SECONDS.seconds else AHEAD_SECONDS.seconds

    // What the browser reports for its own output (Bluetooth included where it knows).
    override val outputLatency: Duration get() = contextOutputLatency().coerceIn(0.0, 1.0).seconds

    // Not used: the microphone's worklet records what this plays, in step with the microphone.
    override fun playedAudio(frames: Int): FloatArray = FloatArray(frames)

    override fun diagnostics(): Map<String, String> = mapOf(
        "outputUnderruns" to playerUnderruns(player).toString(),
        "pianoOn" to if (samples != null) "audio thread" else "main thread",
    )

    override fun close() = playerStop(player)

    private companion object {
        const val CHUNK_FRAMES = 512
        const val AHEAD_SECONDS = 0.25
        /** A message to the worklet takes effect with its next block of 128 frames. */
        const val MESSAGE_SECONDS = 0.01
        const val MAX_FOLLOW_FRAMES = 1 shl 16
    }
}

/** The voices of the worklet of player [player]. */
private class WorkletVoices(private val player: () -> Int) : SampleVoices {
    override fun start(voice: Int, root: Int, step: Double, gain: Double, releaseStep: Double) =
        playerVoiceStart(player(), voice, root, step, gain, releaseStep)

    override fun tune(voice: Int, step: Double) = playerVoice(player(), "tune", voice, step)

    override fun release(voice: Int) = playerVoice(player(), "release", voice, 0.0)

    override fun stop(voice: Int) = playerVoice(player(), "stop", voice, 0.0)
}

/** Hands the browser the recordings it does not have yet (the first batch may come before the rest). */
private fun uploadPiano(samples: SampleSet) {
    for ((root, data) in samples.samples) if (!pianoHas(root)) pianoUpload(root, PackedAudio.pack(data))
}

/** MIDI through the Web MIDI API. */
private class WebMidiBackend : MidiBackend {
    private val changes = MutableSharedFlow<Unit>(extraBufferCapacity = 8)

    init {
        // Asks for access once (the browser may ask the user); devices appear when it is granted.
        midiInit { changes.tryEmit(Unit) }
    }

    // Without Web MIDI (Safari) the microphone and the app's piano still work.
    override val unavailableReason: String? = null

    override val devicesChanged: Flow<Unit> = changes

    override fun inputDevices(): List<String> = midiNames(true).split('\n').filter { it.isNotEmpty() }

    override fun outputDevices(): List<String> = midiNames(false).split('\n').filter { it.isNotEmpty() }

    override fun openInput(name: String): MidiInputPort {
        val messages = MutableSharedFlow<MidiMessage>(extraBufferCapacity = 256)
        val listening = midiListen(name) { status, data1, data2 -> messages.tryEmit(MidiMessage(status, data1, data2)) }
        if (!listening) throw IllegalStateException("MIDI device $name is not connected.")
        return object : MidiInputPort {
            override val messages: Flow<MidiMessage> = messages
            override fun close() = midiUnlisten(name)
        }
    }

    override fun openOutput(name: String): MidiOutputPort {
        return object : MidiOutputPort {
            override fun send(message: MidiMessage) = midiSend(name, message.status, message.data1, message.data2)
            override fun close() = Unit
        }
    }
}

/** The microphone through `getUserMedia`, as unprocessed as the browser allows. */
private class WebAudioInput : AudioInputBackend {
    override val unavailableReason: String? =
        if (hasMicrophoneApi()) null else "This browser gives no access to the microphone (it needs HTTPS or localhost)."

    init {
        if (unavailableReason == null) microphonesWatch()
    }

    override val hasAccess: Boolean get() = hasMicrophoneStream()

    override suspend fun requestAccess(): Boolean = hasAccess || suspendCoroutine { continuation ->
        microphoneRequest { granted -> continuation.resume(granted) }
    }

    // The browser names its microphones only once the page may use one (now or on an earlier visit).
    override fun devices(): List<String> = microphoneNames().split('\n').filter { it.isNotEmpty() }

    /** The named microphone, or the browser's default for null or one that is gone (as the other platforms do). */
    override fun open(name: String?): AudioInputPort {
        if (!hasAccess) throw IllegalStateException("No access to the microphone.")
        return WebAudioPort(name ?: "")
    }
}

private class WebAudioPort(name: String) : AudioInputPort {
    override val sampleRate: Int = audioSampleRate()

    private val received = Channel<AudioBlock>(capacity = 64, onBufferOverflow = BufferOverflow.DROP_OLDEST)

    init {
        // Each block: the microphone's samples, then as many of what the app's piano played meanwhile.
        microphoneStart(name) { packed ->
            val frames = packed.length / 2
            received.trySend(AudioBlock(PackedAudio.unpack(packed, 0, frames), PackedAudio.unpack(packed, frames, frames)))
        }
    }

    override val blocks: Flow<FloatArray> = received.receiveAsFlow().map { it.microphone }

    // The worklet takes the piano's sound in the same audio callback as the microphone's: exactly
    // in step, so [reference] (WebSynthPort.playedAudio) is not needed.
    override fun blocksWith(reference: (frames: Int) -> FloatArray): Flow<AudioBlock> = received.receiveAsFlow()

    override fun close() {
        microphoneStop()
        received.close()
    }
}

/**
 * Recordings in the browser: kept in memory while the exercise runs and handed to the user as
 * downloads when it ends (`session-<date>_<time>.wav` and `.json`), since a page cannot write
 * into a folder by itself.
 */
private class DownloadRecordingStore : RecordingStore {
    override val location: String = "Downloads"

    override fun create(): RecordingFile = object : RecordingFile {
        private val id = recordingCreate()
        override val name: String = recordingName()

        override fun append(bytes: ByteArray) = recordingAppend(id, PackedAudio.packBytes(bytes))

        override fun finish(wavHeader: ByteArray, log: String) = recordingFinish(id, name, PackedAudio.packBytes(wavHeader), log)

        // Another download; saved again, the browser keeps both (the newest counts, see PlayedLabels.savedAt).
        override fun saveLabels(labels: String) = downloadText(PlayedLabels.fileNameFor("$name.wav"), labels)

        override val savesLabelsQuietly = false
    }
}

// ----------------------------------------------------------------------------- JavaScript side

/**
 * The shared state, with the JavaScript halves of [PackedAudio]: `pack` turns Float32Arrays into
 * one string, `unpack` a string (from [start], [length] code units) into a Float32Array,
 * `bytes` a string of bytes into a Uint8Array.
 */
private fun initState(): Unit = js(
    """{
        var s = globalThis.__mbc = globalThis.__mbc || { synths: {}, nextId: 0, listeners: {}, recordings: {}, piano: {} };
        s.pack = function (arrays) {
            var total = 0;
            for (var a = 0; a < arrays.length; a++) total += arrays[a].length;
            var codes = new Uint16Array(total), k = 0;
            for (var a = 0; a < arrays.length; a++) {
                var f = arrays[a];
                for (var i = 0; i < f.length; i++) {
                    var x = f[i] > 1 ? 1 : (f[i] < -1 ? -1 : f[i]);
                    codes[k++] = Math.round(x * 16383) + 16384;
                }
            }
            var parts = [];
            for (var i = 0; i < total; i += 8192) parts.push(String.fromCharCode.apply(null, codes.subarray(i, Math.min(total, i + 8192))));
            return parts.join('');
        };
        s.unpack = function (text, start, length) {
            var f = new Float32Array(length);
            for (var i = 0; i < length; i++) f[i] = (text.charCodeAt(start + i) - 16384) / 16383;
            return f;
        };
        s.bytes = function (text) {
            var b = new Uint8Array(text.length);
            for (var i = 0; i < text.length; i++) b[i] = text.charCodeAt(i);
            return b;
        };
    }""",
)

/** `session-<date>_<time>` in local time, as the other platforms name their recordings. */
private fun recordingName(): String = js(
    """(function () {
        var d = new Date();
        function two(n) { return (n < 10 ? '0' : '') + n; }
        return 'session-' + d.getFullYear() + '-' + two(d.getMonth() + 1) + '-' + two(d.getDate()) +
            '_' + two(d.getHours()) + '-' + two(d.getMinutes()) + '-' + two(d.getSeconds());
    })()""",
)

private fun recordingCreate(): Int = js("(function () { var s = globalThis.__mbc; var id = ++s.nextId; s.recordings[id] = []; return id; })()")

/** Keeps more bytes of recording [id] ([PackedAudio.packBytes]). */
private fun recordingAppend(id: Int, packed: String): Unit = js("{ var s = globalThis.__mbc; s.recordings[id].push(s.bytes(packed)); }")

/** Offers recording [id] as two downloads: the WAV (header first) and the log. */
private fun recordingFinish(id: Int, name: String, packedHeader: String, log: String): Unit = js(
    """{
        var s = globalThis.__mbc;
        var header = s.bytes(packedHeader);
        function save(blob, fileName) {
            var link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = fileName;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            setTimeout(function () { URL.revokeObjectURL(link.href); }, 60000);
        }
        save(new Blob([header].concat(s.recordings[id]), { type: 'audio/wav' }), name + '.wav');
        delete s.recordings[id];
        // A moment later: browsers hold back two downloads started at the very same time.
        setTimeout(function () { save(new Blob([log], { type: 'application/json' }), name + '.json'); }, 500);
    }""",
)

/** Offers [text] as a download named [fileName]. */
private fun downloadText(fileName: String, text: String): Unit = js(
    """{
        var link = document.createElement('a');
        link.href = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        setTimeout(function () { URL.revokeObjectURL(link.href); }, 60000);
    }""",
)

private fun storageGet(key: String): String? = js("window.localStorage.getItem(key)")

private fun storageSet(key: String, value: String): Unit = js("{ window.localStorage.setItem(key, value); }")

private fun storageRemove(key: String): Unit = js("{ window.localStorage.removeItem(key); }")

private fun storageKeys(prefix: String): String =
    js("Object.keys(window.localStorage).filter(function (k) { return k.startsWith(prefix); }).join('\\n')")

/**
 * The shared audio context's sample rate; creates the context with the app's two worklets and
 * wakes it (browsers start it only after a click). The worklets run on the browser's audio thread:
 * "mbc-player" plays the chunks it is sent and the sampled piano's voices (rendered as
 * [io.github.jonnyfrick.musicbootcamp.core.audio.Sampler] does, see RemoteSamplerTest);
 * "mbc-recorder" sends what the microphone hears (first input) together with what the player
 * played in the same callback (second input). Both talk through message ports, which queue while
 * the main thread is busy.
 */
private fun audioSampleRate(): Int = js(
    """(function () {
        var s = globalThis.__mbc;
        if (!s.context) {
            s.context = new (window.AudioContext || window.webkitAudioContext)({ latencyHint: 'interactive' });
            // Into the page's start log (index.html), to tell audio trouble on a device apart.
            if (window.mbcLog) window.mbcLog('audio context ' + s.context.sampleRate + ' Hz, base latency ' + s.context.baseLatency +
                ', output latency ' + s.context.outputLatency + ', ' + s.context.state + ', worklets ' + (typeof AudioWorkletNode));
            var code =
                "class Player extends AudioWorkletProcessor {" +
                "  constructor() { super(); this.queue = []; this.offset = 0; this.consumed = 0; this.played = 0; this.underruns = 0; this.calls = 0; this.started = false;" +
                "    this.samples = {}; this.voices = new Map();" +
                "    this.port.onmessage = (e) => {" +
                "      var m = e.data;" +
                "      if (m instanceof Float32Array) { this.queue.push(m); return; }" +
                "      if (m.t === 'samples') { this.samples = m.samples; return; }" +
                "      if (m.t === 'start') { var d = this.samples[m.root]; if (d) this.voices.set(m.voice, { d: d, pos: 0, step: m.step, gain: m.gain, rs: m.rs, rel: 1, releasing: false }); return; }" +
                "      var v = this.voices.get(m.voice); if (!v) return;" +
                "      if (m.t === 'tune') v.step = m.step; else if (m.t === 'release') v.releasing = true; else if (m.t === 'stop') this.voices.delete(m.voice);" +
                "    }; }" +
                "  process(inputs, outputs) {" +
                "    var out = outputs[0][0]; var i = 0;" +
                "    while (i < out.length && this.queue.length) {" +
                "      var chunk = this.queue[0]; var n = Math.min(out.length - i, chunk.length - this.offset);" +
                "      out.set(chunk.subarray(this.offset, this.offset + n), i); i += n; this.offset += n;" +
                "      if (this.offset >= chunk.length) { this.queue.shift(); this.offset = 0; }" +
                "    }" +
                "    if (i > 0) this.started = true;" +
                "    if (i < out.length && this.started) this.underruns++;" +
                "    this.consumed += i;" +
                "    for (var k = i; k < out.length; k++) out[k] = 0;" +
                "    for (var [id, v] of this.voices) {" +
                "      var alive = true, d = v.d;" +
                "      for (var j = 0; j < out.length; j++) {" +
                "        var index = Math.floor(v.pos);" +
                "        if (index + 1 >= d.length) { alive = false; break; }" +
                "        var a = (d[index] - 16384) / 16383, b = (d[index + 1] - 16384) / 16383;" +
                "        if (v.releasing) v.rel *= v.rs;" +
                "        out[j] += (a + (b - a) * (v.pos - index)) * v.gain * v.rel;" +
                "        v.pos += v.step;" +
                "      }" +
                "      if (!alive || v.rel < 1e-5) this.voices.delete(id);" +
                "    }" +
                "    for (var k = 0; k < out.length; k++) out[k] = out[k] > 1 ? 1 : (out[k] < -1 ? -1 : out[k]);" +
                "    this.played += out.length;" +
                "    if (++this.calls % 4 === 0) this.port.postMessage({ consumed: this.consumed, played: this.played, underruns: this.underruns });" +
                "    return true;" +
                "  }" +
                "}" +
                "registerProcessor('mbc-player', Player);" +
                "class Recorder extends AudioWorkletProcessor {" +
                "  constructor() { super(); this.mic = new Float32Array(1024); this.ref = new Float32Array(1024); this.filled = 0; }" +
                "  process(inputs) {" +
                "    var input = inputs[0][0]; var played = inputs[1] && inputs[1][0];" +
                "    if (input) for (var i = 0; i < input.length; i++) {" +
                "      this.mic[this.filled] = input[i]; this.ref[this.filled] = played ? played[i] : 0;" +
                "      if (++this.filled === this.mic.length) {" +
                "        this.port.postMessage({ mic: this.mic, ref: this.ref }, [this.mic.buffer, this.ref.buffer]);" +
                "        this.mic = new Float32Array(1024); this.ref = new Float32Array(1024); this.filled = 0;" +
                "      }" +
                "    }" +
                "    return true;" +
                "  }" +
                "}" +
                "registerProcessor('mbc-recorder', Recorder);";
            s.worklets = s.context.audioWorklet.addModule(URL.createObjectURL(new Blob([code], { type: 'application/javascript' })));
            // The latest player's sound, as the recorder's second input.
            s.connectReference = function () {
                if (s.reference && s.microphone && s.microphone.node) s.reference.connect(s.microphone.node, 0, 1);
            };
        }
        if (s.context.state === 'suspended') s.context.resume();
        return Math.round(s.context.sampleRate);
    })()""",
)

private fun pianoHas(root: Int): Boolean = js("!!globalThis.__mbc.piano[root]")

/** Keeps the recording of [root] ([PackedAudio], the codes as they are) for the players. */
private fun pianoUpload(root: Int, packed: String): Unit = js(
    """{
        var d = new Uint16Array(packed.length);
        for (var i = 0; i < packed.length; i++) d[i] = packed.charCodeAt(i);
        globalThis.__mbc.piano[root] = d;
    }""",
)

/**
 * Starts a player and returns its id. With [chunk] > 0 it keeps [ahead] frames queued in the
 * worklet, asking [render] for each [chunk] ([PackedAudio]); otherwise it plays the piano's
 * voices, with the recordings handed over now, and reports how far it got through [onPlayed].
 */
private fun playerStart(ahead: Int, chunk: Int, render: () -> String, onPlayed: (Double) -> Unit): Int = js(
    """(function () {
        var s = globalThis.__mbc;
        var id = ++s.nextId;
        var player = { node: null, sent: 0, consumed: 0, played: 0, underruns: 0, timer: 0, stopped: false, pending: [] };
        if (window.mbcLog) window.mbcLog('player ' + id + ' starts: ' + (chunk > 0 ? 'piano rendered by the app, ' + chunk + ' frames a chunk, ' + ahead + ' ahead' : 'sampled piano in the worklet'));
        // Messages for the worklet; queued until it exists (the first note may come before).
        player.post = function (m) { if (player.node) player.node.port.postMessage(m); else player.pending.push(m); };
        s.synths[id] = player;
        function pump() {
            if (!player.node || chunk <= 0) return;
            while (player.sent - player.consumed < ahead) {
                var data = s.unpack(render(), 0, chunk);
                player.node.port.postMessage(data, [data.buffer]);
                player.sent += chunk;
            }
        }
        s.worklets.then(function () {
            if (player.stopped) return;
            player.node = new AudioWorkletNode(s.context, 'mbc-player', { numberOfInputs: 0, numberOfOutputs: 1, outputChannelCount: [1] });
            if (chunk <= 0) player.node.port.postMessage({ t: 'samples', samples: s.piano });
            player.pending.forEach(function (m) { player.node.port.postMessage(m); });
            player.pending = [];
            player.node.port.onmessage = function (e) {
                player.consumed = e.data.consumed; player.played = e.data.played; player.underruns = e.data.underruns;
                if (chunk > 0) pump(); else onPlayed(player.played);
            };
            player.node.connect(s.context.destination);
            s.reference = player.node;
            s.connectReference();
            pump();
        });
        // Also on a timer: the worklet's reports stop coming while the audio context is suspended.
        if (chunk > 0) player.timer = setInterval(pump, 20);
        return id;
    })()""",
)

/** Tells player [id] to start [voice]: [root]'s recording read on by [step] per frame at [gain], dying away by [releaseStep] once released. */
private fun playerVoiceStart(id: Int, voice: Int, root: Int, step: Double, gain: Double, releaseStep: Double): Unit = js(
    """{
        var p = globalThis.__mbc.synths[id];
        if (p) p.post({ t: 'start', voice: voice, root: root, step: step, gain: gain, rs: releaseStep });
    }""",
)

/** Tells player [id] to "tune" [voice] to [step], "release" or "stop" it. */
private fun playerVoice(id: Int, what: String, voice: Int, step: Double): Unit = js(
    """{
        var p = globalThis.__mbc.synths[id];
        if (p) p.post({ t: what, voice: voice, step: step });
    }""",
)

private fun contextOutputLatency(): Double =
    js("(function () { var c = globalThis.__mbc.context; return c ? ((c.outputLatency || 0) + (c.baseLatency || 0)) : 0; })()")

private fun playerUnderruns(id: Int): Int = js("(function () { var p = globalThis.__mbc.synths[id]; return p ? p.underruns : 0; })()")

private fun playerStop(id: Int): Unit = js(
    """{
        var s = globalThis.__mbc;
        var player = s.synths[id];
        if (player) {
            if (window.mbcLog) window.mbcLog('player ' + id + ' stops: played ' + player.played + ' frames, underruns ' + player.underruns +
                (s.context ? ', context ' + s.context.sampleRate + ' Hz, output latency ' + s.context.outputLatency + ', ' + s.context.state : '') +
                (s.decodeMillis ? ', samples decoded in ' + Math.round(s.decodeMillis) + ' ms' : ''));
            player.stopped = true;
            clearInterval(player.timer);
            if (player.node) {
                player.node.port.onmessage = null;
                player.node.disconnect();
                if (s.reference === player.node) s.reference = null;
            }
            delete s.synths[id];
        }
    }""",
)

private fun midiInit(onChange: () -> Unit): Unit = js(
    """{
        if (navigator.requestMIDIAccess) {
            navigator.requestMIDIAccess().then(function (access) {
                globalThis.__mbc.midi = access;
                access.onstatechange = function () { onChange(); };
                onChange();
            }, function () { });
        }
    }""",
)

/** The names of the MIDI inputs or outputs, one per line. */
private fun midiNames(inputs: Boolean): String = js(
    """(function () {
        var access = globalThis.__mbc.midi;
        if (!access) return '';
        var names = [];
        (inputs ? access.inputs : access.outputs).forEach(function (port) { if (port.state !== 'disconnected') names.push(port.name); });
        return names.join('\n');
    })()""",
)

/** Calls [onMessage] for every channel message of the input called [name]; false if there is none. */
private fun midiListen(name: String, onMessage: (Int, Int, Int) -> Unit): Boolean = js(
    """(function () {
        var access = globalThis.__mbc.midi;
        if (!access) return false;
        var found = false;
        access.inputs.forEach(function (port) {
            if (found || port.name !== name) return;
            found = true;
            port.onmidimessage = function (e) {
                var d = e.data;
                if (d.length > 0 && d[0] >= 0x80 && d[0] < 0xF0) onMessage(d[0], d.length > 1 ? d[1] : 0, d.length > 2 ? d[2] : 0);
            };
        });
        return found;
    })()""",
)

private fun midiUnlisten(name: String): Unit = js(
    """{
        var access = globalThis.__mbc.midi;
        if (access) access.inputs.forEach(function (port) { if (port.name === name) port.onmidimessage = null; });
    }""",
)

private fun midiSend(name: String, status: Int, data1: Int, data2: Int): Unit = js(
    """{
        var access = globalThis.__mbc.midi;
        if (access) access.outputs.forEach(function (port) {
            if (port.name === name) port.send((status & 0xF0) === 0xC0 || (status & 0xF0) === 0xD0 ? [status, data1] : [status, data1, data2]);
        });
    }""",
)

/** Decodes the file in [data] (one byte per character); [done] gets its sample rate and samples packed as by [decodeInBrowser], or 0 and null. */
private fun decodeAudio(data: String, done: (Int, String?) -> Unit): Unit = js(
    """{
        var started = performance.now();
        var bytes = new Uint8Array(data.length);
        for (var i = 0; i < data.length; i++) bytes[i] = data.charCodeAt(i);
        // An offline context at the file's own rate: decoding resamples to the context's rate.
        var context = new OfflineAudioContext(1, 1, 44100);
        context.decodeAudioData(bytes.buffer).then(function (buffer) {
            var samples = buffer.getChannelData(0);
            var parts = [];
            for (var i = 0; i < samples.length; i += 8192) {
                var n = Math.min(8192, samples.length - i);
                var codes = new Array(n);
                for (var j = 0; j < n; j++) codes[j] = Math.round(Math.max(-1, Math.min(1, samples[i + j])) * 16383) + 16384;
                parts.push(String.fromCharCode.apply(null, codes));
            }
            var s = globalThis.__mbc;
            s.decodeMillis = (s.decodeMillis || 0) + performance.now() - started;
            done(buffer.sampleRate, parts.join(''));
        }, function () { done(0, null); });
    }""",
)

private fun hasMicrophoneApi(): Boolean = js("!!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia)")

private fun hasMicrophoneStream(): Boolean = js("!!globalThis.__mbc.stream")

/**
 * Keeps `__mbc.microphones` the list of the browser's microphones, by name and id, as they come and
 * go. Their names come only once the page may use a microphone; until then the list is empty.
 * The browser's "default" and "communications" entries are left out: the app's own choice
 * "system default" stands for them.
 */
private fun microphonesWatch(): Unit = js(
    """{
        var s = globalThis.__mbc;
        s.microphones = [];
        s.listMicrophones = function () {
            if (!(navigator.mediaDevices && navigator.mediaDevices.enumerateDevices)) return Promise.resolve();
            return navigator.mediaDevices.enumerateDevices().then(function (devices) {
                var list = [], seen = {};
                devices.forEach(function (d) {
                    if (d.kind !== 'audioinput' || !d.label || d.deviceId === 'default' || d.deviceId === 'communications') return;
                    var name = d.label, n = 2;
                    while (seen[name]) name = d.label + ' (' + n++ + ')';
                    seen[name] = true;
                    list.push({ name: name, id: d.deviceId });
                });
                s.microphones = list;
            }, function () {});
        };
        s.microphoneConstraints = function (id) {
            // Without the processing meant for calls, which would distort a piano.
            var c = { echoCancellation: false, noiseSuppression: false, autoGainControl: false };
            if (id) c.deviceId = { exact: id };
            return { audio: c };
        };
        s.listMicrophones();
        if (navigator.mediaDevices && navigator.mediaDevices.addEventListener) {
            navigator.mediaDevices.addEventListener('devicechange', function () { s.listMicrophones(); });
        }
    }""",
)

private fun microphoneNames(): String =
    js("(globalThis.__mbc.microphones || []).map(function (m) { return m.name; }).join('\\n')")

/** Asks for the browser's default microphone; once allowed, the microphones have names. */
private fun microphoneRequest(done: (Boolean) -> Unit): Unit = js(
    """{
        var s = globalThis.__mbc;
        navigator.mediaDevices.getUserMedia(s.microphoneConstraints(''))
            .then(function (stream) {
                s.stream = stream;
                s.streamDevice = '';
                return s.listMicrophones();
            })
            .then(function () { done(true); }, function () { done(false); });
    }""",
)

/**
 * Delivers the microphone [name] (the browser's default for "" or one that is gone) block by block,
 * each packed with what the player played meanwhile ([PackedAudio]). The stream of another
 * microphone is stopped once this one's is open, so only one is in use.
 */
private fun microphoneStart(name: String, deliver: (String) -> Unit): Unit = js(
    """{
        var s = globalThis.__mbc;
        var microphone = { stopped: false };
        s.microphone = microphone;
        var id = '';
        (s.microphones || []).forEach(function (m) { if (m.name === name) id = m.id; });
        var stream = id === (s.streamDevice || '') ? Promise.resolve(s.stream)
            : navigator.mediaDevices.getUserMedia(s.microphoneConstraints(id)).then(function (opened) {
                if (s.stream) s.stream.getTracks().forEach(function (t) { t.stop(); });
                s.stream = opened;
                s.streamDevice = id;
                return opened;
            }, function () { return s.stream; });
        Promise.all([s.worklets, stream]).then(function (ready) {
            if (microphone.stopped) return;
            microphone.source = s.context.createMediaStreamSource(ready[1]);
            microphone.node = new AudioWorkletNode(s.context, 'mbc-recorder', { numberOfInputs: 2, numberOfOutputs: 1, outputChannelCount: [1] });
            microphone.node.port.onmessage = function (e) { deliver(s.pack([e.data.mic, e.data.ref])); };
            // A node only runs while it leads to the output; it writes nothing there, so the microphone stays off the loudspeaker.
            microphone.source.connect(microphone.node, 0, 0);
            microphone.node.connect(s.context.destination);
            s.connectReference();
        });
    }""",
)

private fun microphoneStop(): Unit = js(
    """{
        var m = globalThis.__mbc.microphone;
        if (m) {
            m.stopped = true;
            if (m.node) { m.node.port.onmessage = null; m.source.disconnect(); m.node.disconnect(); }
        }
        globalThis.__mbc.microphone = null;
    }""",
)
