package io.github.jonnyfrick.musicbootcamp.core.midi

enum class Accidental { NONE, SHARP, FLAT }

/** A note on the grand staff: [step] lines and spaces above middle C (negative below), spelled as [NoteNames] does. */
data class StaffNote(val step: Int, val accidental: Accidental)

/** Where notes sit on the grand staff: treble clef from middle C up, bass clef below, one ledger line between. */
object Staff {
    /** The staves' lines, as steps. */
    val TREBLE_LINES = listOf(2, 4, 6, 8, 10)
    val BASS_LINES = listOf(-10, -8, -6, -4, -2)

    const val TOP_LINE = 10
    const val BOTTOM_LINE = -10

    private val STEPS = listOf(0, 0, 1, 2, 2, 3, 3, 4, 4, 5, 6, 6) // C C# D Eb E F F# G G# A Bb B
    private val ACCIDENTALS = mapOf(1 to Accidental.SHARP, 3 to Accidental.FLAT, 6 to Accidental.SHARP, 8 to Accidental.SHARP, 10 to Accidental.FLAT)

    fun note(midiNote: Int): StaffNote {
        val pitchClass = midiNote.mod(12)
        return StaffNote((midiNote.floorDiv(12) - 5) * 7 + STEPS[pitchClass], ACCIDENTALS[pitchClass] ?: Accidental.NONE)
    }

    /** The short lines a note at [step] needs, as steps. */
    fun ledgerLines(step: Int): List<Int> = when {
        step == 0 -> listOf(0)
        step > TOP_LINE -> (TOP_LINE + 2..step step 2).toList()
        step < BOTTOM_LINE -> (step.floorDiv(2) * 2 + (if (step.mod(2) == 0) 0 else 2)..BOTTOM_LINE - 2 step 2).toList()
        else -> emptyList()
    }
}
