package io.github.jonnyfrick.musicbootcamp.ui

import androidx.compose.foundation.Canvas
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.rotate
import androidx.compose.ui.semantics.contentDescription
import androidx.compose.ui.semantics.semantics
import io.github.jonnyfrick.musicbootcamp.core.midi.Accidental
import io.github.jonnyfrick.musicbootcamp.core.midi.Staff
import io.github.jonnyfrick.musicbootcamp.core.midi.StaffNote
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.min

/**
 * [notes] on the grand staff. Its scale comes from [range], the exercise's notes (ledger lines
 * included), so it stays put from note to note. Everything is drawn, not set in a font: the web
 * app has none with musical signs.
 */
@Composable
internal fun GrandStaff(notes: List<Int>, range: IntRange, description: String, modifier: Modifier = Modifier) {
    val ink = MaterialTheme.colorScheme.onSurface
    val lines = MaterialTheme.colorScheme.onSurfaceVariant
    val highest = max(Staff.TOP_LINE, Staff.note(range.last).step)
    val lowest = min(Staff.BOTTOM_LINE, Staff.note(range.first).step)
    Canvas(modifier.semantics { contentDescription = description }) {
        // One step is half a line's distance; a little room above and below.
        val step = size.height / (highest - lowest + 3)
        fun y(staffStep: Int) = (highest + 1.5f - staffStep) * step
        val gap = 2 * step
        val thin = max(1f, step / 5)

        (Staff.TREBLE_LINES + Staff.BASS_LINES).forEach { line ->
            drawLine(lines, Offset(0f, y(line)), Offset(size.width, y(line)), thin)
        }
        drawLine(lines, Offset(thin / 2, y(10)), Offset(thin / 2, y(-10)), thin)
        drawLine(lines, Offset(size.width - thin / 2, y(10)), Offset(size.width - thin / 2, y(-10)), thin)
        val clefX = gap * 1.6f
        trebleClef(Offset(clefX, y(4)), gap, ink)
        bassClef(Offset(clefX, y(-4)), gap, ink)

        val staffNotes = notes.distinct().map(Staff::note).sortedBy { it.step }
        val center = (clefX + gap * 1.6f + size.width) / 2
        var offsetSide = false
        staffNotes.forEachIndexed { index, note ->
            // A second above the note below goes to the other side of the stem's place.
            offsetSide = index > 0 && note.step - staffNotes[index - 1].step == 1 && !offsetSide
            val x = center + if (offsetSide) gap * 1.25f else 0f
            Staff.ledgerLines(note.step).forEach { line ->
                drawLine(lines, Offset(x - gap * 1.05f, y(line)), Offset(x + gap * 1.05f, y(line)), thin * 1.3f)
            }
            noteHead(Offset(x, y(note.step)), gap, ink)
            // Close accidentals step aside from each other.
            val crowded = staffNotes.subList(0, index).count { it.accidental != Accidental.NONE && abs(it.step - note.step) < 6 }
            accidental(note, Offset(center - gap * (1.6f + 1.1f * (crowded % 2)), y(note.step)), gap, ink)
        }
    }
}

private fun DrawScope.noteHead(at: Offset, gap: Float, color: Color) {
    rotate(-20f, at) {
        drawOval(color, Offset(at.x - gap * 0.62f, at.y - gap * 0.44f), Size(gap * 1.24f, gap * 0.88f))
    }
}

private fun DrawScope.accidental(note: StaffNote, at: Offset, gap: Float, color: Color) {
    val width = gap * 0.11f
    when (note.accidental) {
        Accidental.NONE -> Unit
        Accidental.SHARP -> {
            val x = gap * 0.2f
            for (side in listOf(-x, x)) drawLine(color, Offset(at.x + side, at.y - gap * 1.05f), Offset(at.x + side, at.y + gap * 1.05f), width)
            for (level in listOf(-gap * 0.33f, gap * 0.33f)) {
                drawLine(color, Offset(at.x - gap * 0.45f, at.y + level + gap * 0.12f), Offset(at.x + gap * 0.45f, at.y + level - gap * 0.12f), width * 2.4f)
            }
        }
        Accidental.FLAT -> {
            drawLine(color, Offset(at.x - gap * 0.3f, at.y - gap * 1.6f), Offset(at.x - gap * 0.3f, at.y + gap * 0.5f), width * 1.4f)
            val bowl = Path().apply {
                moveTo(at.x - gap * 0.3f, at.y - gap * 0.15f)
                cubicTo(at.x + gap * 0.1f, at.y - gap * 0.6f, at.x + gap * 0.65f, at.y - gap * 0.4f, at.x + gap * 0.3f, at.y + gap * 0.05f)
                cubicTo(at.x + gap * 0.15f, at.y + gap * 0.25f, at.x - gap * 0.1f, at.y + gap * 0.4f, at.x - gap * 0.3f, at.y + gap * 0.5f)
            }
            drawPath(bowl, color, style = Stroke(width * 2f))
        }
    }
}

/** A treble clef curling around the G line at [g]; its curve in line distances, x right, y down. */
private fun DrawScope.trebleClef(g: Offset, gap: Float, color: Color) {
    fun x(value: Float) = g.x + value * gap
    fun y(value: Float) = g.y + value * gap
    val path = Path().apply {
        moveTo(x(0.15f), y(0.75f))
        cubicTo(x(-0.55f), y(0.7f), x(-0.65f), y(-0.35f), x(0.1f), y(-0.45f))
        cubicTo(x(0.95f), y(-0.5f), x(1.05f), y(0.85f), x(0.05f), y(1.0f))
        cubicTo(x(-1.2f), y(1.1f), x(-1.5f), y(-0.6f), x(-0.2f), y(-1.9f))
        cubicTo(x(0.5f), y(-2.6f), x(0.9f), y(-3.2f), x(0.7f), y(-4.0f))
        cubicTo(x(0.6f), y(-4.6f), x(0.2f), y(-4.5f), x(0.05f), y(-3.9f))
        cubicTo(x(-0.1f), y(-3.0f), x(0.2f), y(0.5f), x(0.45f), y(2.3f))
        cubicTo(x(0.6f), y(3.2f), x(-0.5f), y(3.4f), x(-0.6f), y(2.7f))
    }
    drawPath(path, color, style = Stroke(gap * 0.17f, cap = StrokeCap.Round))
    drawCircle(color, gap * 0.24f, Offset(x(-0.45f), y(2.65f)))
}

/** A bass clef with its dot on the F line at [f]. */
private fun DrawScope.bassClef(f: Offset, gap: Float, color: Color) {
    fun x(value: Float) = f.x + value * gap
    fun y(value: Float) = f.y + value * gap
    val path = Path().apply {
        moveTo(x(-0.7f), y(0.1f))
        cubicTo(x(-0.8f), y(-0.95f), x(0.8f), y(-1.1f), x(0.9f), y(0.1f))
        cubicTo(x(0.95f), y(1.3f), x(0f), y(2.1f), x(-0.9f), y(2.6f))
    }
    drawPath(path, color, style = Stroke(gap * 0.2f, cap = StrokeCap.Round))
    drawCircle(color, gap * 0.26f, Offset(x(-0.5f), y(0.05f)))
    drawCircle(color, gap * 0.15f, Offset(x(1.3f), y(-0.5f)))
    drawCircle(color, gap * 0.15f, Offset(x(1.3f), y(0.5f)))
}
