package io.github.jonnyfrick.musicbootcamp.core.audio

import io.github.jonnyfrick.musicbootcamp.core.learning.LearnedSequences
import io.github.jonnyfrick.musicbootcamp.core.midi.MidiMessage
import io.github.jonnyfrick.musicbootcamp.core.model.KotlinRandomSource
import io.github.jonnyfrick.musicbootcamp.core.model.PracticeMode
import io.github.jonnyfrick.musicbootcamp.core.model.PracticeSettings
import io.github.jonnyfrick.musicbootcamp.core.practice.AnswerUse
import io.github.jonnyfrick.musicbootcamp.core.practice.PracticeSession

/**
 * What was really played in a recorded run, from a MIDI keyboard's key presses logged alongside
 * the microphone ([RecordingEventType.PLAYED]): each step's answer as the exercise assigns answers
 * ([PracticeSession] giving the recorded notes; a key pressed sooner than [reactionSeconds] after
 * a step began answers an older one; a step given up [toleranceSeconds] after the next began).
 * Per step (1-based) the notes counted for it, empty if none; null without key presses logged.
 */
fun playedFromMidi(
    events: List<RecordingEvent>,
    sampleRate: Int,
    reactionSeconds: Double = 0.6,
    toleranceSeconds: Double = 1.2,
): Map<Int, List<Int>>? {
    val presses = events.filter { it.type == RecordingEventType.PLAYED }
    if (presses.isEmpty()) return null
    val steps = events.filter { it.type == RecordingEventType.STEP }
    if (steps.isEmpty()) return emptyMap()
    val voices = steps.maxOf { it.notes.size }
    val settings = PracticeSettings(mode = if (voices > 1) PracticeMode.TWO_VOICES_PURE_RANDOM else PracticeMode.MONOPHONIC)
    val session = PracticeSession(settings, LearnedSequences(), KotlinRandomSource(), script = steps.map { it.notes }.iterator()) { }
    val reaction = (reactionSeconds * sampleRate).toLong()
    val tolerance = (toleranceSeconds * sampleRate).toLong()

    // The timeline: steps, the tolerance's ends (added as steps are given), key presses.
    class Event(val sample: Long, val order: Int, val run: () -> Unit)
    val pending = mutableListOf<Event>()
    val counted = mutableMapOf<Int, List<Int>>()
    var stepStart = Long.MIN_VALUE
    fun collect() = session.takeAssignments().forEach { if (it.use == AnswerUse.COUNTED && it.step != null) counted[it.step + 1] = it.notes }
    for (step in steps) {
        pending += Event(step.sample, 0) {
            val result = session.step(deferEvaluation = true)
            stepStart = step.sample
            result.openStep?.let { number -> pending += Event(step.sample + tolerance, 1) { session.expire(number); collect() } }
        }
    }
    for (press in presses) {
        pending += Event(press.sample, 2) {
            press.notes.forEach { session.onMidiInput(MidiMessage.noteOn(it, 100), beforeReaction = press.sample - stepStart < reaction) }
            collect()
        }
    }
    while (pending.isNotEmpty()) {
        val next = pending.minWith(compareBy({ it.sample }, { it.order }))
        pending.remove(next)
        next.run()
    }
    session.end()
    collect()
    return steps.indices.associate { (it + 1) to counted[it + 1].orEmpty().distinct().sorted() }
}
