/**
 * The main screen (Java: the run dialog): what the app plays, how it went, and Start / Stop as
 * the floating action button. The exercise's settings open in a bottom sheet on phones and
 * stay open in a side pane on wide windows.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
internal fun PracticeScreen(controller: AppController, snackbar: SnackbarHostState) {
    val wide = isWideWindow()
    var sheet by rememberSaveable { mutableStateOf(false) }

    Scaffold(
        topBar = {
            SetupTopBar(controller) {
                if (!wide) {
                    IconButton(onClick = { sheet = true }) {
                        Icon(AppIcons.Tune, contentDescription = stringResource(Res.string.customize_exercise))
                    }
                }
            }
        },
        // On wide windows the button belongs to the practice area, not over the exercise pane.
        floatingActionButton = { if (!wide) StartStopButton(controller) },
        snackbarHost = { SnackbarHost(snackbar) },
    ) { padding ->
        if (wide) {
            Row(Modifier.fillMaxSize().padding(padding)) {
                Box(Modifier.weight(1f).fillMaxHeight()) {
                    PracticeContent(controller, onCustomize = null, modifier = Modifier)
                    StartStopButton(controller, Modifier.align(Alignment.BottomEnd).padding(16.dp))
                }
                VerticalDivider()
                Surface(color = MaterialTheme.colorScheme.surfaceContainerLow, modifier = Modifier.width(400.dp).fillMaxHeight()) {
                    Column(Modifier.verticalScroll(rememberScrollState()).padding(bottom = 16.dp)) {
                        Text(
                            stringResource(Res.string.exercise),
                            style = MaterialTheme.typography.titleLarge,
                            modifier = Modifier.padding(start = SettingPadding, top = 16.dp, end = SettingPadding),
                        )
                        ExerciseSettings(controller)
                    }
                }
            }
        } else {
            PracticeContent(controller, onCustomize = { sheet = true }, modifier = Modifier.padding(padding))
        }
    }

    if (sheet && !wide) {
        ModalBottomSheet(onDismissRequest = { sheet = false }, sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)) {
            Text(
                stringResource(Res.string.exercise),
                style = MaterialTheme.typography.titleLarge,
                modifier = Modifier.padding(horizontal = SettingPadding),
            )
            Column(Modifier.verticalScroll(rememberScrollState()).padding(bottom = 24.dp)) {
                ExerciseSettings(controller)
            }
        }
    }
}

/** Start / Stop, the screen's main action. */
@Composable
private fun StartStopButton(controller: AppController, modifier: Modifier = Modifier) {
    val running = controller.running
    // The extended FAB does not pass its text on to screen readers by itself.
    val label = stringResource(if (running) Res.string.stop else Res.string.start)
    ExtendedFloatingActionButton(
        onClick = if (running) controller::stopPractice else controller::startPractice,
        icon = { Icon(if (running) AppIcons.Stop else AppIcons.Play, contentDescription = null) },
        text = { Text(label) },
        modifier = modifier.semantics { contentDescription = label },
        containerColor = if (running) MaterialTheme.colorScheme.errorContainer else MaterialTheme.colorScheme.primaryContainer,
        contentColor = if (running) MaterialTheme.colorScheme.onErrorContainer else MaterialTheme.colorScheme.onPrimaryContainer,
    )
}

@Composable
private fun PracticeContent(controller: AppController, onCustomize: (() -> Unit)?, modifier: Modifier) {
    val settings = controller.settings
    val status = controller.status
    val running = controller.running

    CenteredColumn(modifier, bottomSpace = 96.dp) {
        controller.midiUnavailableReason?.let { reason ->
            Card(
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer),
                modifier = Modifier.fillMaxWidth().padding(horizontal = SettingPadding, vertical = 8.dp),
            ) {
                Text(reason, Modifier.padding(16.dp), color = MaterialTheme.colorScheme.onErrorContainer)
            }
        }

        // What the exercise is; on phones a tap opens its settings.
        val summary = stringResource(
            Res.string.practice_summary,
            modeLabel(settings.mode),
            controller.noteName(settings.lowLimit),
            controller.noteName(settings.highLimit),
            settings.breathingTime.toString(),
        )
        if (onCustomize != null) {
            FilterChip(
                selected = false,
                onClick = onCustomize,
                label = { Text(summary) },
                leadingIcon = { Icon(AppIcons.Tune, contentDescription = null, modifier = Modifier.size(18.dp)) },
                modifier = Modifier.padding(horizontal = SettingPadding),
            )
        } else {
            Text(
                summary,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.padding(horizontal = SettingPadding, vertical = 8.dp),
            )
        }

        PracticeStage(status, controller.feedback, running, settings, controller.preferences.givenNotes, controller::noteName, controller::shownNote, controller.heardKeys, controller::playKey)

        Row(Modifier.fillMaxWidth().padding(horizontal = SettingPadding, vertical = 12.dp), horizontalArrangement = Arrangement.SpaceEvenly) {
            Stat(stringResource(Res.string.stat_steps), status.steps)
            Stat(stringResource(Res.string.stat_correct), status.correct, MaterialTheme.extendedColors.correct)
            Stat(stringResource(Res.string.stat_wrong), status.wrong, MaterialTheme.colorScheme.error)
            Stat(stringResource(Res.string.stat_stored), status.storedMistakes)
        }

        Row(Modifier.padding(horizontal = SettingPadding), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            val preferences = controller.preferences
            fun show(notes: GivenNotes) = controller.setGivenNotes(if (preferences.givenNotes == notes) GivenNotes.HIDDEN else notes)
            ToggleChip(Res.string.show_names, preferences.givenNotes == GivenNotes.NAMES) { show(GivenNotes.NAMES) }
            ToggleChip(Res.string.show_staff, preferences.givenNotes == GivenNotes.STAFF) { show(GivenNotes.STAFF) }
            // What the app plays is decided when the exercise starts.
            ToggleChip(Res.string.sight_reading, !preferences.playsGivenNotes, enabled = !running) { controller.setSightReading(preferences.playsGivenNotes) }
        }

        if (!running) controller.runSummary?.let { RunSummaryCard(it, controller) }
    }
}

@Composable
private fun ToggleChip(label: StringResource, selected: Boolean, enabled: Boolean = true, onClick: () -> Unit) {
    FilterChip(
        selected = selected,
        enabled = enabled,
        onClick = onClick,
        label = { Text(stringResource(label)) },
        leadingIcon = if (selected) {
            { Icon(AppIcons.Check, contentDescription = null, modifier = Modifier.size(18.dp)) }
        } else {
            null
        },
    )
}

@Composable
private fun Stat(label: String, value: Int, color: Color = Color.Unspecified) {
    Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.semantics(mergeDescendants = true) {}) {
        Text(value.toString(), style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.SemiBold, color = color)
        Text(label, style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
    }
}

/** After a run in optimization mode: each step with what was recognised. */
@Composable
private fun RunSummaryCard(summary: RunSummary, controller: AppController) {
    val noteName: (Int) -> String = controller::noteName
    var editing by remember { mutableStateOf<StepSummary?>(null) }
    editing?.let { step ->
        PlayedDialog(step.number, step.given, playedOf(controller.playedLabels, step.number), noteName) { played ->
            when (played) {
                Played.AsGiven -> if (step.number in controller.playedLabels) controller.clearPlayed(step.number)
                is Played.Notes -> controller.setPlayed(step.number, played.notes)
                Played.Nothing -> controller.setPlayed(step.number, emptyList())
                Played.Unknown -> controller.setPlayed(step.number, null)
            }
            editing = null
        }
    }
    Card(Modifier.fillMaxWidth().padding(horizontal = SettingPadding, vertical = 12.dp)) {
        Column(Modifier.fillMaxWidth().padding(16.dp), verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(stringResource(Res.string.run_summary_title), style = MaterialTheme.typography.titleMedium)
            Text(
                stringResource(Res.string.run_summary_label_hint) + " " + stringResource(Res.string.run_summary_hint),
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            VerticalSpace()
            val reasons = mapOf(
                AnswerUse.ECHO to stringResource(Res.string.run_summary_echo),
                AnswerUse.TOO_LATE to stringResource(Res.string.run_summary_too_late),
                AnswerUse.NOT_EXPECTED to stringResource(Res.string.run_summary_not_expected),
            )
            val late = stringResource(Res.string.run_summary_late)
            val heardLabel = stringResource(Res.string.run_summary_heard)
            val playedLabel = stringResource(Res.string.run_summary_played)
            fun notes(notes: List<Int>) = notes.joinToString(" ") { noteName(it) }
            for (step in summary.steps) {
                val played = when (val label = playedOf(controller.playedLabels, step.number)) {
                    // The MIDI keyboard's truth, where it was logged (what the player marks overrides it).
                    Played.AsGiven -> step.playedMidi?.let { "MIDI: " + (notes(it).ifEmpty { "–" }) }
                    is Played.Notes -> notes(label.notes)
                    Played.Nothing -> "–"
                    Played.Unknown -> "?"
                }
                val heard = (listOf(notes(step.detected)) + step.ignored.map { (ignored, use) -> "(${notes(ignored)}: ${reasons[use]})" })
                    .filter { it.isNotEmpty() }.joinToString(" ").ifEmpty { "–" }
                SummaryRow(
                    number = step.number,
                    correct = step.correct,
                    given = notes(step.given),
                    counted = step.counted?.let { notes(it) + if (step.countedLate) " ($late)" else "" } ?: "–",
                    detail = "$heardLabel: $heard",
                    played = played?.let { "$playedLabel: $it" },
                    onClick = { editing = step },
                )
            }
            VerticalSpace()
            OutlinedButton(onClick = { controller.savePlayedLabels() }, enabled = !controller.labelsSaved) {
                Text(stringResource(Res.string.run_summary_save_labels))
            }
            Text(
                stringResource(Res.string.run_summary_recording, summary.recording),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * One step of the run summary: given → what counted for it, ✓ or ✗; below, smaller, what was
 * heard and — if the player marked it — what they played. Tapping it marks what was played.
 */
@Composable
private fun SummaryRow(
    number: Int,
    correct: Boolean?,
    given: String,
    counted: String,
    detail: String,
    played: String?,
    onClick: () -> Unit,
) {
    val color = if (correct == false) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.onSurface
    Column(Modifier.fillMaxWidth().clickable(onClick = onClick).padding(vertical = 4.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(number.toString(), style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant,
                fontFamily = FontFamily.Monospace, modifier = Modifier.width(32.dp))
            Text(
                when (correct) { true -> "✓"; false -> "✗"; null -> "" },
                style = MaterialTheme.typography.bodyLarge, color = color, modifier = Modifier.width(24.dp),
            )
            Text("$given  →  $counted", style = MaterialTheme.typography.bodyLarge, color = color, modifier = Modifier.weight(1f))
        }
        Row {
            Spacer(Modifier.width(56.dp))
            Column(Modifier.weight(1f)) {
                played?.let { Text(it, style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.primary) }
                Text(detail, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
            }
        }
    }
}
