package io.github.jonnyfrick.musicbootcamp.core.pitch

import io.github.jonnyfrick.musicbootcamp.core.midi.Tuning
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.max
import kotlin.math.roundToInt
import kotlin.math.sqrt
import kotlin.time.Duration

/**
 * One recognition for single notes and chords: what a key stroke (or several keys struck
 * together) played, for any number of voices.
 *
 * Strokes are found as for single notes ([NoteTracker], which also learns the app's own sound
 * from the reference). Each stroke is then analysed on its own, in a window that grows hop by hop
 * from just after the attack: what was ringing before the stroke and the app's predicted sound
 * are removed frequency by frequency, and [HarmonicChordRecognizer] weighs the hypotheses (the
 * chords expected now, their near misses, the strongest partial patterns). The stroke is decided
 * as soon as one hypothesis leads clearly and steadily — a single note after a few hops, a chord
 * with deep notes later — and at the latest when the window reaches its maximum or the next
 * stroke begins (which never pushes an undecided stroke aside).
 */
class StrokeRecognizer(
    val sampleRate: Int,
    private val voices: Int,
    range: IntRange,
    private val referenceAHz: Double = Tuning.STANDARD_A_HZ,
    private val parameters: ChordDetectionParameters = ChordDetectionParameters(),
    learned: LearnedTemplates = LearnedTemplates(),
    instrument: InstrumentProfile = InstrumentProfile.PIANO,
    private val expected: () -> List<List<Int>> = { emptyList() },
    /** The shortest delay the app's own sound can have (see [NoteTracker]). */
    shortestEchoDelay: Duration = Duration.ZERO,
    /** Single notes: the given notes' octaves count as right too, so they get the given notes' bias as well. */
    private val octavesCountAsCorrect: Boolean = false,
    /** What an earlier run learned about the app's sound (see [NoteTracker]). */
    echoStart: EchoState? = null,
) {
    private val strokes = NoteTracker(sampleRate, referenceAHz, parameters.strokes, instrument, shortestEchoDelay = shortestEchoDelay, echoStart = echoStart)

    /** What it has learned about the app's sound, for the next run. */
    fun echoState(): EchoState? = strokes.echoState()
    private val windowStart = (instrument.chordWindowStartMillis ?: parameters.windowStartMillis) * sampleRate / 1000
    private val minWindow = parameters.minWindowMillis * sampleRate / 1000
    private val maxWindow = maxOf(
        (parameters.windowEndMillis + (instrument.chordWindowStartMillis?.let { it - parameters.windowStartMillis } ?: 0)) * sampleRate / 1000 - windowStart,
        minWindow,
    )
    private val spread = (instrument.chordSpreadMillis ?: parameters.chordSpreadMillis) * sampleRate / 1000
    private val candidates = (range.first - RANGE_MARGIN).coerceAtLeast(LogSpectrum.LOWEST_NOTE)..(range.last + RANGE_MARGIN).coerceAtMost(LogSpectrum.HIGHEST_NOTE - 12)
    private val recognizer = HarmonicChordRecognizer(candidates, parameters, learned, instrument)
    private val decisionMargin = if (voices > 1) parameters.chordDecisionMargin else parameters.decisionMargin
    // The app's sound: its own piano (stretched partials), any note it may play.
    private val appRecognizer = HarmonicChordRecognizer(LogSpectrum.LOWEST_NOTE + 12..LogSpectrum.HIGHEST_NOTE - 24, parameters)

    private val microphone = FloatArray(HISTORY_SECONDS * sampleRate)
    private val reference = FloatArray(HISTORY_SECONDS * sampleRate)
    private var written = 0L

    private class Pending(val onset: Long, val ownSoundRemoved: Boolean, val level: Double, val atAppAttack: Boolean) {
        /** Where the window ends at the latest (the next stroke). */
        var end = Long.MAX_VALUE
        var lastAnalysed = -1L
        var best: RecognizedChord? = null
        var steady = 0
        /** Where the window starts; after what remained of an attack of the app's, it starts anew. */
        var from = onset
        var restarts = 0
        /** Pitch classes the app plays in the window, recognised from the reference (only at an app attack). */
        var appClasses: Set<Int> = emptySet()
    }

    private val pending = ArrayDeque<Pending>()
    /** When an attack of the app's last reached the microphone. */
    private var lastAppAttack = Long.MIN_VALUE / 2
    private var lastDecided = Long.MIN_VALUE / 2
    private val found = mutableListOf<DetectedChord>()

    /** RMS of the latest hop, for a level meter. */
    val level: Double get() = strokes.level

    /** How long the app's sound takes to reach the microphone, once measured. */
    val echoDelay: Duration? get() = strokes.echoDelay

    /** Receives what the stroke detection saw in every hop, for analysing recordings. */
    var trace: ((HopTrace) -> Unit)? = null

    /** Receives every analysis of a stroke (onset, window, result) and decision, for analysing recordings. */
    var decisionTrace: ((String) -> Unit)? = null

    init {
        strokes.trace = { hop ->
            trace?.invoke(hop)
            if (hop.referenceOnsetNear) lastAppAttack = hop.sampleTime
            if (hop.onset) onStroke(hop.sampleTime - strokes.hopSize, hop.ownSoundRemoved, hop.level, hop.ownSoundRemoved && hop.referenceOnsetNear)
        }
    }


    /** Feeds samples (mono, -1..1) and what the app played meanwhile; returns the strokes decided in them. */
    fun process(samples: FloatArray, reference: FloatArray? = null): List<DetectedChord> {
        found.clear()
        var offset = 0
        while (offset < samples.size) {
            val end = minOf(samples.size, offset + strokes.hopSize)
            for (i in offset until end) {
                val slot = ((written + i - offset) % microphone.size).toInt()
                microphone[slot] = samples[i]
                this.reference[slot] = reference?.get(i) ?: 0f
            }
            strokes.process(samples.copyOfRange(offset, end), reference?.copyOfRange(offset, end))
            written += end - offset
            offset = end
            analysePending()
        }
        return found.toList()
    }

    private fun onStroke(onset: Long, ownSoundRemoved: Boolean, level: Double, atAppAttack: Boolean) {
        val last = pending.lastOrNull()
        if (last != null && onset - last.onset < spread) {
            // The same chord (fingers a little apart), or the beating of close notes; only a clearly
            // louder stroke starts anew.
            if (level < RESTART_RISE * last.level) return
            pending.remove(last)
        }
        pending.forEach { it.end = minOf(it.end, onset) }
        pending.addLast(Pending(onset, ownSoundRemoved, level, atAppAttack))
    }

    private fun analysePending() {
        val iterator = pending.iterator()
        while (iterator.hasNext()) {
            val stroke = iterator.next()
            val from = stroke.from + windowStart
            val limit = minOf(stroke.end, from + maxWindow)
            val to = minOf(written, limit)
            val length = to - from
            val over = written >= limit
            if (length >= minWindow && to > stroke.lastAnalysed) {
                stroke.lastAnalysed = to
                val result = analyse(stroke, from, to)
                if (result != null && result.notes == stroke.best?.notes) stroke.steady++ else stroke.steady = if (result != null) 1 else 0
                stroke.best = result
                val margin = result?.let { (it.alternativeScore ?: Double.MAX_VALUE) - it.score } ?: 0.0
                decisionTrace?.invoke(
                    "stroke@${stroke.onset} window ${stroke.from - stroke.onset}+${length} " +
                        (result?.let { "${it.notes} ${fmt(it.score)} vs ${it.alternative} ${it.alternativeScore?.let(::fmt)} steady ${stroke.steady}" } ?: "nothing") +
                        (if (stroke.atAppAttack) " at app attack ${stroke.appClasses}" else ""),
                )
                if (result != null && stroke.steady >= parameters.steadyAnalyses && margin >= decisionMargin) {
                    if (decide(stroke, result)) {
                        iterator.remove()
                        continue
                    }
                }
            }
            if (over) {
                stroke.best?.let { decide(stroke, it) }
                iterator.remove()
            }
        }
    }

    /**
     * Reports [chord] for [stroke]; false if it is the note the app is sounding: then the window
     * starts anew from now, when the app's note is predicted well, and may still show a note the
     * player struck with the app's. At an attack of the app's that is what remains of it, and is
     * dropped if it stays; a stroke of the player's while the app's attack is still ringing (the
     * prediction removes it least well at first) is reported as it ends up.
     */
    private fun decide(stroke: Pending, chord: RecognizedChord): Boolean {
        val echo = strokes.ownSound
        // Single notes only: a chord answered right is the app's chord (and an answer to an earlier
        // one that came with the app's attack is the reaction-time rule's to sort out).
        val sounding = voices == 1 && echo != null && chord.notes.all { echo.soundsAt(LogSpectrum.frequencyOf(it.toDouble(), referenceAHz)) }
        val classes = chord.notes.all { it.mod(12) in stroke.appClasses }
        // Only the newest note given can be what remains of the app's attack: the player answers the
        // ones before, which may still ring in the app's sound (unknown without expectations).
        val given = expected()
        val newest = given.lastOrNull().orEmpty().map { it.mod(12) }.toSet()
        val older = given.dropLast(1).flatten().map { it.mod(12) }.toSet()
        val ofNewest = given.isEmpty() || chord.notes.all { it.mod(12) in newest }
        // Away from an attack: struck sooner after the app's note was heard than the player can
        // react, it cannot be their answer to it; the attack still rings, not removed well enough.
        // (Not if an earlier note given was the same: that may be the player's answer.)
        val tooSoon = stroke.onset - lastAppAttack < REACTION_SECONDS * sampleRate
        val appNotes = voices == 1 && echo != null && ofNewest &&
            if (stroke.atAppAttack) classes || sounding else classes && tooSoon && chord.notes.none { it.mod(12) in older }
        decisionTrace?.invoke("stroke@${stroke.onset} decided ${chord.notes}" + if (appNotes) " = the app's (restart ${stroke.restarts})" else "")
        if (appNotes && stroke.restarts >= MAX_RESTARTS && !stroke.atAppAttack) return report(stroke, chord)
        if (appNotes) {
            if (stroke.restarts++ >= MAX_RESTARTS) return true.also { stroke.best = null }
            stroke.from = written - windowStart
            stroke.best = null
            stroke.steady = 0
            return false
        }
        return report(stroke, chord)
    }

    private fun report(stroke: Pending, chord: RecognizedChord): Boolean {
        found += DetectedChord(chord.notes, written, stroke.onset, stroke.ownSoundRemoved, chord)
        lastDecided = stroke.onset
        return true
    }

    private fun fmt(value: Double) = ((value * 1000).roundToInt() / 1000.0).toString()

    /** Hann windows by length: the windows of every stroke grow through the same lengths. */
    private val windows = HashMap<Int, DoubleArray>()

    /** The chord in [from, to) after removing what rang before the stroke and the app's predicted sound. */
    private fun analyse(stroke: Pending, from: Long, to: Long): RecognizedChord? {
        val length = (to - from).toInt()
        val size = nextPowerOfTwo(maxOf(length, MIN_FFT))
        if (windows.size > WINDOWS_KEPT) windows.clear() // a window cut short by the next stroke may have any length
        val window = windows.getOrPut(length) { DoubleArray(length) { 0.5 - 0.5 * cos(2 * PI * it / length) } }
        val windowEnergy = window.sumOf { it * it }

        val mic = power(microphone, from, length, window, size, 0)
        // What rang before: the same length right before the stroke, and — with chords, while the
        // last one decided still rings — that chord at its full strength (the beating of close notes
        // looks like new strokes, which bring nothing new then). Not for single notes: the player's
        // previous answer still rings when the next comes, and shares partials with it.
        val before = power(microphone, stroke.onset - length, length, window, size, 0)
        val background = if (voices > 1 && stroke.onset - lastDecided in 1 until RINGING_SECONDS * sampleRate) {
            val ringing = power(microphone, lastDecided + windowStart, length, window, size, 0)
            DoubleArray(before.size) { max(before[it], ringing[it]) }
        } else {
            before
        }
        val echo = strokes.ownSound?.takeIf { stroke.ownSoundRemoved }
        // What the app played into the window (also for the app-attack check below).
        val played = echo?.delayHops?.let { delayHops -> power(reference, from, length, window, size, delayHops * strokes.hopSize) }
        val own = played?.let { power -> DoubleArray(power.size) { k -> power[k] * echo.ownSoundGain(k.toDouble() * sampleRate / size) } }
        val remaining = DoubleArray(mic.size) { k ->
            val removed = max(parameters.backgroundWeight * background[k], own?.get(k) ?: 0.0)
            (mic[k] - removed).coerceAtLeast(0.0)
        }
        fun rms(power: DoubleArray) = sqrt(2 * power.sum() / (size * windowEnergy))
        val remainingLevel = rms(remaining)
        if (remainingLevel < parameters.minLevel || remainingLevel < parameters.minNewShare * rms(mic)) return null
        // Which notes the app plays, from its clean reference (a phone's loudspeaker hardly
        // reproduces a low note's fundamental, so the predicted sound alone misses them).
        // (Single notes only: with chords the app's and the answer share pitch classes too often.)
        if (voices == 1 && played != null) {
            stroke.appClasses = appRecognizer.recognize(LogSpectrum.fromPower(played, size, sampleRate, referenceAHz), voices, emptyList())
                ?.notes?.map { it.mod(12) }?.toSet().orEmpty()
        }
        val spectrum = LogSpectrum.fromPower(remaining, size, sampleRate, referenceAHz)
        return recognizer.recognize(spectrum, voices, expectedAnswers())
    }

    /** The answers expected: the notes given lately, with a single note's octaves where they count as right. */
    private fun expectedAnswers(): List<List<Int>> {
        val given = expected()
        if (voices > 1 || !octavesCountAsCorrect) return given
        return given.flatten().flatMap { note -> OCTAVES.map { note + it } }.filter { it in candidates }.distinct().map { listOf(it) }
    }

    /** Hann-windowed power spectrum (up to Nyquist) of [length] samples of [signal] from [start], [lag] samples earlier. */
    private fun power(signal: FloatArray, start: Long, length: Int, window: DoubleArray, size: Int, lag: Int): DoubleArray {
        val re = DoubleArray(size)
        val im = DoubleArray(size)
        for (i in 0 until length) {
            val position = start - lag + i
            val sample = if (position < 0 || position >= written || position < written - signal.size) 0f
            else signal[(position % signal.size).toInt()]
            re[i] = sample * window[i]
        }
        fftReal(re, im)
        return DoubleArray(size / 2 + 1) { k -> re[k] * re[k] + im[k] * im[k] }
    }

    private companion object {
        const val HISTORY_SECONDS = 4
        const val RANGE_MARGIN = 2
        const val RESTART_RISE = 2.0
        const val MIN_FFT = 4096
        const val WINDOWS_KEPT = 64
        val OCTAVES = listOf(0, -12, 12, -24, 24)
        /** The shortest time from hearing a note to striking the answer (as PracticeRunner.REACTION_TIME). */
        const val REACTION_SECONDS = 0.4
        const val MAX_RESTARTS = 2
        const val RINGING_SECONDS = 1
    }
}

/** Microphone blocks (with what the app played) → recognised strokes; see [StrokeRecognizer]. */
fun Flow<AudioBlock>.recognizedStrokes(
    sampleRate: Int,
    voices: Int,
    range: IntRange,
    referenceAHz: Double,
    parameters: ChordDetectionParameters = ChordDetectionParameters(),
    learned: LearnedTemplates = LearnedTemplates(),
    expected: () -> List<List<Int>> = { emptyList() },
    onLevel: (Double) -> Unit = {},
    instrument: InstrumentProfile = InstrumentProfile.PIANO,
    onEchoDelay: (Duration) -> Unit = {},
    shortestEchoDelay: Duration = Duration.ZERO,
    octavesCountAsCorrect: Boolean = false,
    echoStart: EchoState? = null,
    onEchoState: (EchoState) -> Unit = {},
): Flow<DetectedChord> = flow {
    val recognizer = StrokeRecognizer(sampleRate, voices, range, referenceAHz, parameters, learned, instrument, expected, shortestEchoDelay, octavesCountAsCorrect, echoStart)
    var blocks = 0
    collect { block ->
        val chords = recognizer.process(block.microphone, block.reference)
        onLevel(recognizer.level)
        recognizer.echoDelay?.let(onEchoDelay)
        if (++blocks % ECHO_STATE_BLOCKS == 0) recognizer.echoState()?.let(onEchoState)
        chords.forEach { emit(it) }
    }
}
