package io.github.jonnyfrick.musicbootcamp.core.audio

import io.github.jonnyfrick.musicbootcamp.core.midi.MidiMessage
import io.github.jonnyfrick.musicbootcamp.core.midi.MidiOutput
import io.github.jonnyfrick.musicbootcamp.core.persistence.SetupRepository
import io.github.jonnyfrick.musicbootcamp.core.pitch.DetectedChord
import io.github.jonnyfrick.musicbootcamp.core.pitch.DetectedNote
import io.github.jonnyfrick.musicbootcamp.core.practice.AnswerUse
import io.github.jonnyfrick.musicbootcamp.core.practice.Assignment
import io.github.jonnyfrick.musicbootcamp.core.practice.Evaluation
import io.github.jonnyfrick.musicbootcamp.core.practice.StepResult
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.serialization.Serializable

/** Where a recording goes: the audio as it arrives, the header and the event log at the end. */
interface RecordingFile {
    /** A name to show the user, e.g. the file path. */
    val name: String

    fun append(bytes: ByteArray)

    /** Writes [wavHeader] at the start of the audio and stores [log] next to it. */
    fun finish(wavHeader: ByteArray, log: String)

    /** Stores what the player really played ([PlayedLabels] as JSON) next to the recording, replacing earlier ones. */
    fun saveLabels(labels: String) {}

    /** Whether [saveLabels] goes unnoticed (a file is written), so it may happen on every change; false where each is a download. */
    val savesLabelsQuietly: Boolean get() = true
}

@Serializable
enum class RecordingEventType {
    /** The app started a note. */
    APP_NOTE_ON,
    APP_NOTE_OFF,

    /** Pitch detection recognised a note (before the own-sound filter). */
    DETECTED,

    /** A detected note that reached the exercise. */
    ACCEPTED,

    /** A new step started; [RecordingEvent.notes] are the given notes. */
    STEP,

    /** A step was evaluated; [RecordingEvent.correct] says how. */
    EVALUATION,

    /** A key pressed on a MIDI keyboard logged as the truth alongside the microphone (see [playedFromMidi]). */
    PLAYED,

    /**
     * What became of an answer: [RecordingEvent.step] (1-based) it counted for, or why none
     * ([RecordingEvent.use], an [AnswerUse]).
     */
    ASSIGNED,
}

@Serializable
data class RecordingEvent(
    /** Position in the recording, in samples. */
    val sample: Long,
    val type: RecordingEventType,
    val notes: List<Int> = emptyList(),
    val cents: Double? = null,
    val correct: Boolean? = null,
    val step: Int? = null,
    val use: String? = null,
    /** With [RecordingEventType.ASSIGNED]: struck only once the next step's note was heard (null in older logs). */
    val late: Boolean? = null,
)

@Serializable
data class RecordingLog(
    val version: Int = 1,
    val sampleRate: Int,
    /** What the channels of the WAV file hold, e.g. `microphone`, `reference`. */
    val channels: List<String>,
    /** Settings that matter for replaying the recording (tolerance, headphones, tuning, …). */
    val info: Map<String, String> = emptyMap(),
    val events: List<RecordingEvent>,
)

/** One step of a recorded run, so the player can say where they played something else. */
data class StepSummary(
    /** 1-based. */
    val number: Int,
    val given: List<Int>,
    /** Notes recognised between this step's start and the next one's. */
    val detected: List<Int>,
    /** Of those, the ones that reached the exercise. */
    val accepted: List<Int>,
    /** The evaluation of this step; null if it never happened (e.g. stopped by hand). */
    val correct: Boolean?,
    /** The answer that counted for this step (heard maybe a step later); null: none (missed). */
    val counted: List<Int>? = null,
    /** Whether [counted] was struck only once the next step's note could be heard. */
    val countedLate: Boolean = false,
    /** Answers heard in this step's time that counted for no step, and why. */
    val ignored: List<Pair<List<Int>, AnswerUse>> = emptyList(),
    /** What the MIDI keyboard says was really played for this step (empty: nothing); null without one. */
    val playedMidi: List<Int>? = null,
)

/**
 * Records a practice session with microphone input: the audio the pitch detection gets, as a
 * WAV file, and a log of what the app played, what was recognised and how steps were evaluated.
 * Replaying it tunes the recognition on real sound instead of synthetic tones.
 *
 * [audio] is called as the audio arrives, [detected] from the recognition (with the learned model
 * maybe a little later, in another coroutine), the other events from the exercise dispatcher; each
 * keeps its own state. [finish] merges the events once all have stopped.
 */
class SessionRecorder(
    private val file: RecordingFile,
    val sampleRate: Int,
    private val channelNames: List<String>,
) {
    private val samplesWritten = MutableStateFlow(0L) // written by the audio side only
    private val audioEvents = mutableListOf<RecordingEvent>()
    private val exerciseEvents = mutableListOf<RecordingEvent>()
    private var bytesWritten = 0L

    val name: String get() = file.name

    /** One block per channel, in the order of the channel names. */
    fun audio(channels: List<FloatArray>) {
        require(channels.size == channelNames.size) { "Expected ${channelNames.size} channels" }
        val bytes = Wav.pcm16(channels)
        file.append(bytes)
        bytesWritten += bytes.size
        samplesWritten.value += channels.first().size
    }

    /** [DetectedNote.sampleTime] counts from the same first block as this recording. */
    fun detected(note: DetectedNote) {
        audioEvents += RecordingEvent(note.sampleTime, RecordingEventType.DETECTED, listOf(note.midiNote), cents = note.cents)
    }

    /** A chord from [io.github.jonnyfrick.musicbootcamp.core.pitch.ChordTracker], logged like a note, with all its notes. */
    fun detectedChord(chord: DetectedChord) {
        audioEvents += RecordingEvent(chord.sampleTime, RecordingEventType.DETECTED, chord.notes)
    }

    fun accepted(message: MidiMessage) = exerciseEvent(RecordingEventType.ACCEPTED, listOf(message.data1))

    /** A key pressed on the MIDI keyboard that tells what was really played (not used by the exercise). */
    fun played(message: MidiMessage) = exerciseEvent(RecordingEventType.PLAYED, listOf(message.data1))

    fun step(result: StepResult) {
        result.previousCorrect?.let { exerciseEvent(RecordingEventType.EVALUATION, correct = it) }
        exerciseEvent(RecordingEventType.STEP, result.given)
    }

    fun evaluation(evaluation: Evaluation) = exerciseEvent(RecordingEventType.EVALUATION, correct = evaluation.correct)

    fun assignment(assignment: Assignment) {
        exerciseEvents += RecordingEvent(
            samplesWritten.value, RecordingEventType.ASSIGNED, assignment.notes,
            step = assignment.step?.plus(1), use = assignment.use.name, late = assignment.late,
        )
    }

    /** Wraps the app's output so every note it plays is logged. */
    fun recording(output: MidiOutput) = MidiOutput { message ->
        when {
            message.isNoteOn -> exerciseEvent(RecordingEventType.APP_NOTE_ON, listOf(message.data1))
            message.command == MidiMessage.NOTE_OFF || message.command == MidiMessage.NOTE_ON ->
                exerciseEvent(RecordingEventType.APP_NOTE_OFF, listOf(message.data1))
        }
        output.send(message)
    }

    /** Call once the audio has stopped and the exercise has ended. */
    fun finish(info: Map<String, String>) {
        val events = allEvents()
        val log = RecordingLog(sampleRate = sampleRate, channels = channelNames, info = info, events = events)
        file.finish(Wav.header(sampleRate, channelNames.size, bytesWritten), SetupRepository.json.encodeToString(log))
    }

    /** Step by step what happened; call after [finish] (or once audio and exercise have stopped). */
    fun summary(): List<StepSummary> = summarize(allEvents(), sampleRate)

    /** Stores what the player says they really played (after [finish]). */
    fun saveLabels(labels: PlayedLabels) = file.saveLabels(labels.toJson())

    /** See [RecordingFile.savesLabelsQuietly]. */
    val savesLabelsQuietly: Boolean get() = file.savesLabelsQuietly

    private fun allEvents() = (audioEvents + exerciseEvents).sortedBy { it.sample }

    // Exercise events happen "now": at the end of the audio received so far (one block of jitter).
    private fun exerciseEvent(type: RecordingEventType, notes: List<Int> = emptyList(), correct: Boolean? = null) {
        exerciseEvents += RecordingEvent(samplesWritten.value, type, notes, correct = correct)
    }
}

/**
 * Groups a recording's events (sorted by sample, in logging order where equal) by step: each event
 * belongs to the step started last before it; the n-th evaluation belongs to the n-th step.
 */
fun summarize(events: List<RecordingEvent>, sampleRate: Int = 44_100): List<StepSummary> {
    val midi = playedFromMidi(events, sampleRate)
    val given = mutableListOf<List<Int>>()
    val detected = mutableListOf<MutableList<Int>>()
    val accepted = mutableListOf<MutableList<Int>>()
    val counted = mutableMapOf<Int, Pair<List<Int>, Boolean>>() // step (1-based) to answer, late
    val ignored = mutableListOf<MutableList<Pair<List<Int>, AnswerUse>>>()
    for (event in events) {
        when (event.type) {
            RecordingEventType.STEP -> {
                given += event.notes
                detected += mutableListOf<Int>()
                accepted += mutableListOf<Int>()
                ignored += mutableListOf<Pair<List<Int>, AnswerUse>>()
            }
            RecordingEventType.DETECTED -> detected.lastOrNull()?.addAll(event.notes)
            RecordingEventType.ACCEPTED -> accepted.lastOrNull()?.addAll(event.notes)
            RecordingEventType.ASSIGNED -> {
                val use = event.use?.let { name -> AnswerUse.entries.firstOrNull { it.name == name } }
                val step = event.step
                if (use == AnswerUse.COUNTED && step != null) {
                    // Without a tolerance every key press of the step counts (one note-on each).
                    val before = counted[step]
                    // Older logs do not say: then late is heard after the next step began.
                    counted[step] = (before?.first.orEmpty() + event.notes) to (before?.second ?: event.late ?: (step < given.size))
                } else if (use != null) {
                    ignored.lastOrNull()?.add(event.notes to use)
                }
            }
            else -> Unit
        }
    }
    val evaluations = events.filter { it.type == RecordingEventType.EVALUATION }.map { it.correct }
    return given.indices.map { i ->
        StepSummary(
            i + 1, given[i], detected[i], accepted[i], evaluations.getOrNull(i),
            counted = counted[i + 1]?.first, countedLate = counted[i + 1]?.second == true, ignored = ignored[i],
            playedMidi = midi?.get(i + 1),
        )
    }
}
